/* ---------- map ---------- */
var T=60,MW=40,MH=30,WW=MW*T,WH=MH*T;
var solid=new Uint8Array(MW*MH);          // 0 free, 1 wall, 2 crate
var crateAt=new Array(MW*MH);
var wallRects=[],crates=[],vents=[];
function addWall(tx,ty,tw,th,kind){
  wallRects.push({x:tx*T,y:ty*T,w:tw*T,h:th*T,kind:kind,n:wallRects.length});
  for(var y=ty;y<ty+th;y++)for(var x=tx;x<tx+tw;x++)solid[y*MW+x]=1;
}
var LAB={id:'lab',w:40,h:30,start:[1200,900],hub:[19.5,14.5],theme:'lab',
  walls:[[8,8,8,1,'glass'],[24,8,8,1,'glass'],[8,21,8,1,'glass'],[24,21,8,1,'glass'],[12,12,1,6,'glass'],[27,12,1,6,'glass'],
 [5,14,2,2,'tank'],[33,14,2,2,'tank'],[19,4,2,2,'tank'],[19,24,2,2,'tank'],
 [17,12,1,1,'rack'],[22,12,1,1,'rack'],[17,17,1,1,'rack'],[22,17,1,1,'rack'],
 [4,4,1,3,'bench'],[35,4,1,3,'bench'],[4,23,1,3,'bench'],[35,23,1,3,'bench']],
  doors:[{x:30*T,y:T/2,h:true},{x:10*T,y:30*T-T/2,h:true},{x:T/2,y:8*T,h:false},{x:40*T-T/2,y:22*T,h:false}],
  flick:[{x:420,y:420},{x:1980,y:1380},{x:1200,y:420},{x:420,y:1320},{x:1900,y:520}],
  vents:[[2,2],[20,1],[37,2],[38,15],[37,27],[20,28],[2,27],[1,15]],
  zones:[{x:1,y:1,w:11,h:28,rgb:'70,220,120',name:'BIO LAB',code:'SECTOR A',lx:6.5,ly:11},
    {x:28,y:1,w:11,h:28,rgb:'90,200,255',name:'CRYO STORAGE',code:'SECTOR B',lx:33.5,ly:11},
    {x:12,y:1,w:16,h:7,rgb:'190,120,255',name:'SPECIMEN HOLDING',code:'SECTOR C',lx:20,ly:2.6},
    {x:12,y:22,w:16,h:7,rgb:'255,170,60',name:'REACTOR CONTROL',code:'SECTOR D',lx:20,ly:27},
    {x:13,y:9,w:14,h:12,rgb:'47,245,192',name:'CONTAINMENT HUB',code:'SUBLEVEL 9',lx:20,ly:19.6}],
  frost:[29,2,38,28],bio:[[6.5,7.5],[6.5,19.5]],ring:true,crates:32,barrels:12,shields:3};
var MAP=LAB,DOORS=[],FLICK=[],MS=4;
function buildMap(def){
  MAP=def;MW=def.w;MH=def.h;WW=MW*T;WH=MH*T;
  solid=new Uint8Array(MW*MH);crateAt=new Array(MW*MH);flow=new Int16Array(MW*MH);fq=new Int16Array(MW*MH);
  wallRects=[];crates=[];vents=[];
  addWall(0,0,MW,1,'border');addWall(0,MH-1,MW,1,'border');addWall(0,1,1,MH-2,'border');addWall(MW-1,1,1,MH-2,'border');
  if(def.carve){if(!def.rocks)def.rocks=carveWalls(def);def.rocks.forEach(function(w){addWall(w[0],w[1],w[2],w[3],w[4]);});}
  def.walls.forEach(function(w){addWall(w[0],w[1],w[2],w[3],w[4]);});
  DOORS=def.doors;FLICK=def.flick;
  def.vents.forEach(function(v){vents.push({tx:v[0],ty:v[1],x:(v[0]+0.5)*T,y:(v[1]+0.5)*T});});
  floorC.width=WW;floorC.height=WH;decC.width=WW;decC.height=WH;decG=decC.getContext('2d');
  MS=Math.min(160/MW,120/MH);mmC.width=Math.ceil(MW*MS);mmC.height=Math.ceil(MH*MS);
  bakeFloor();bakeMini();
}
function addCrate(tx,ty,barrel){
  if(tx<2||ty<2||tx>MW-3||ty>MH-3)return null;
  var idx=ty*MW+tx;if(solid[idx])return null;
  if(MAP.hub&&Math.abs(tx-MAP.hub[0])<3.6&&Math.abs(ty-MAP.hub[1])<3.6)return null;
  if(MAP.keep)for(var kk=0;kk<MAP.keep.length;kk++)if(Math.abs(tx+0.5-MAP.keep[kk][0]-0.5)<MAP.keep[kk][2]&&Math.abs(ty+0.5-MAP.keep[kk][1]-0.5)<MAP.keep[kk][2])return null;
  if(player&&Math.abs((tx+0.5)*T-player.x)<3*T&&Math.abs((ty+0.5)*T-player.y)<3*T)return null;
  for(var k=0;k<vents.length;k++)if(Math.abs(tx-vents[k].tx)<=2&&Math.abs(ty-vents[k].ty)<=2)return null;
  for(k=0;k<DOORS.length;k++)if(Math.abs((tx+0.5)*T-DOORS[k].x)<3.2*T&&Math.abs((ty+0.5)*T-DOORS[k].y)<3.2*T)return null;
  var c=barrel?{tx:tx,ty:ty,x:tx*T+11,y:ty*T+11,w:38,h:38,hp:16,hit:0,dead:false,v:0,barrel:true,fuse:0,shield:false}
              :{tx:tx,ty:ty,x:tx*T+7,y:ty*T+7,w:46,h:46,hp:40,hit:0,dead:false,v:randi(0,2),barrel:false,fuse:0,shield:false};
  crates.push(c);solid[idx]=2;crateAt[idx]=c;return c;
}
function hideShields(want){
  var plain=crates.filter(function(c){return !c.dead&&!c.barrel&&!c.shield;});
  var have=crates.filter(function(c){return !c.dead&&c.shield;}).length;
  while(have<want&&plain.length){plain.splice(Math.floor(Math.random()*plain.length),1)[0].shield=true;have++;}
}
function genCrates(){
  var i;for(i=0;i<solid.length;i++){if(solid[i]===2)solid[i]=0;crateAt[i]=null;}
  crates.length=0;
  var tries=0,n=0;
  while(n<MAP.crates&&tries++<3000){
    var tx=randi(2,MW-3),ty=randi(2,MH-3);
    if(addCrate(tx,ty,false)){n++;if(Math.random()<0.4){if(addCrate(tx+(Math.random()<0.5?1:0),ty+1,false))n++;}}
  }
  tries=0;n=0;
  while(n<MAP.barrels&&tries++<3000){if(addCrate(randi(2,MW-3),randi(2,MH-3),true))n++;}
  hideShields(MAP.shields);
}
function supplyDrop(){
  var tries=0,n=0,b=0,i,room=42-crates.filter(function(c){return !c.barrel&&!c.dead;}).length;
  while(n<Math.min(5,room)&&tries++<400){if(addCrate(randi(2,MW-3),randi(2,MH-3),false))n++;}
  for(i=0;i<crates.length;i++)if(crates[i].barrel&&!crates[i].dead)b++;
  tries=0;while(b<7&&tries++<200){if(addCrate(randi(2,MW-3),randi(2,MH-3),true))b++;}
  hideShields(2);flowT=0;
}
/* baked floor + persistent decal layer */
var floorC=document.createElement('canvas');floorC.width=WW;floorC.height=WH;
var decC=document.createElement('canvas');decC.width=WW;decC.height=WH;
var decG=decC.getContext('2d');
function glowSprite(rgb){
  var c=document.createElement('canvas');c.width=c.height=128;
  var g=c.getContext('2d'),gr=g.createRadialGradient(64,64,0,64,64,64);
  gr.addColorStop(0,'rgba('+rgb+',1)');gr.addColorStop(0.4,'rgba('+rgb+',0.45)');gr.addColorStop(1,'rgba('+rgb+',0)');
  g.fillStyle=gr;g.fillRect(0,0,128,128);return c;
}
var SPR_W=glowSprite('205,232,255'),SPR_R=glowSprite('255,50,40'),SPR_G=glowSprite('80,255,130');
function bakeFloor(){
  var g=floorC.getContext('2d'),x,y,i,k;
  // sterile lab tiles with a half-tile seam
  for(y=0;y<MH;y++)for(x=0;x<MW;x++){
    var v=Math.floor(rand(0,6)),fb=MAP.floor||[27,34,42];
    g.fillStyle='rgb('+(fb[0]+v)+','+(fb[1]+v)+','+(fb[2]+v)+')';g.fillRect(x*T,y*T,T,T);
    g.fillStyle='rgba(255,255,255,0.025)';g.fillRect(x*T+2,y*T+2,T/2-3,T/2-3);g.fillRect(x*T+T/2+1,y*T+T/2+1,T/2-3,T/2-3);
    if(Math.random()<0.05){g.fillStyle='rgba(0,0,0,0.25)';g.fillRect(x*T+5,y*T+5,T-10,T-10);}
  }
  g.strokeStyle='rgba(12,18,24,0.9)';g.lineWidth=2;g.beginPath();
  for(x=0;x<=MW;x++){g.moveTo(x*T,0);g.lineTo(x*T,WH);}
  for(y=0;y<=MH;y++){g.moveTo(0,y*T);g.lineTo(WW,y*T);}
  g.stroke();
  g.strokeStyle='rgba(120,150,170,0.07)';g.lineWidth=1;g.beginPath();
  for(x=0;x<MW;x++){g.moveTo(x*T+T/2,0);g.lineTo(x*T+T/2,WH);}
  for(y=0;y<MH;y++){g.moveTo(0,y*T+T/2);g.lineTo(WW,y*T+T/2);}
  g.stroke();
  // lab sectors: tint, dashed boundary, stencilled names
  var Z=MAP.zones||[];
  g.textAlign='center';g.textBaseline='middle';
  Z.forEach(function(z){
    g.fillStyle='rgba('+z.rgb+',0.055)';g.fillRect(z.x*T,z.y*T,z.w*T,z.h*T);
    g.strokeStyle='rgba('+z.rgb+',0.4)';g.lineWidth=4;g.setLineDash([26,18]);
    g.strokeRect(z.x*T+12,z.y*T+12,z.w*T-24,z.h*T-24);g.setLineDash([]);
    g.font='bold 46px "Consolas","Courier New",monospace';g.fillStyle='rgba('+z.rgb+',0.2)';g.fillText(z.name,z.lx*T,z.ly*T);
    g.font='bold 18px "Consolas","Courier New",monospace';g.fillStyle='rgba('+z.rgb+',0.3)';g.fillText(z.code,z.lx*T,z.ly*T+38);
  });
  var HX=MAP.hub?(MAP.hub[0]+0.5)*T:WW/2,HY=MAP.hub?(MAP.hub[1]+0.5)*T:WH/2;
  if(MAP.ring){
  g.strokeStyle='rgba(240,200,50,0.3)';g.lineWidth=5;g.setLineDash([40,24]);g.beginPath();
  g.moveTo(T+20,HY);g.lineTo(WW-T-20,HY);g.moveTo(HX,T+20);g.lineTo(HX,WH-T-20);g.stroke();g.setLineDash([]);
  g.strokeStyle='rgba(47,245,192,0.45)';g.lineWidth=6;g.beginPath();g.arc(HX,HY,150,0,TAU);g.stroke();
  g.lineWidth=2;g.beginPath();g.arc(HX,HY,120,0,TAU);g.stroke();
  for(i=0;i<12;i++){var aa=i*TAU/12;g.fillStyle=i%2?'rgba(240,200,50,0.45)':'rgba(20,20,20,0.6)';g.beginPath();g.arc(HX,HY,150,aa,aa+TAU/12);g.arc(HX,HY,135,aa+TAU/12,aa,true);g.fill();}
  }
  if(MAP.hive)bakeHive(g);
  // overhead light pools
  g.globalAlpha=0.16;
  for(y=3;y<MH;y+=5)for(x=3;x<MW;x+=5)g.drawImage(SPR_W,x*T-200,y*T-200,400,400);
  g.globalAlpha=1;
  // cryo frost, bio hazard emblems, drains
  if(MAP.frost)for(i=0;i<26*(MAP.frostN||1);i++){var fr=MAP.frost;g.fillStyle='rgba(220,245,255,'+rand(0.03,0.09)+')';g.beginPath();g.arc(rand(fr[0]*T,fr[2]*T),rand(fr[1]*T,fr[3]*T),rand(20,70),0,TAU);g.fill();}
  (MAP.bio||[]).map(function(b){return [b[0]*T,b[1]*T];}).forEach(function(b){
    g.strokeStyle='rgba(70,220,120,0.4)';g.lineWidth=7;
    for(k=0;k<3;k++){var ba=k*TAU/3-Math.PI/2;g.beginPath();g.arc(b[0]+Math.cos(ba)*26,b[1]+Math.sin(ba)*26,24,0,TAU);g.stroke();}
    g.fillStyle='rgba(70,220,120,0.4)';g.beginPath();g.arc(b[0],b[1],9,0,TAU);g.fill();
  });
  for(i=0;i<14;i++){
    var dx=randi(2,MW-3)*T+30,dy=randi(2,MH-3)*T+30;
    g.fillStyle='#0b1014';g.fillRect(dx-11,dy-11,22,22);g.strokeStyle='#44525e';g.lineWidth=2;g.strokeRect(dx-11,dy-11,22,22);
    g.beginPath();for(k=-6;k<=6;k+=4){g.moveTo(dx-8,dy+k);g.lineTo(dx+8,dy+k);}g.stroke();
  }
  // signs of what happened: old blood trails, scattered papers, grime
  for(i=0;i<12;i++){
    var bx=rand(2*T,WW-2*T),by=rand(2*T,WH-2*T),ba2=rand(0,TAU),bl=rand(60,220);
    for(k=0;k<26;k++){var t=k/26;g.fillStyle='rgba(120,12,12,'+rand(0.12,0.3)+')';g.beginPath();
      g.arc(bx+Math.cos(ba2)*bl*t+rand(-7,7),by+Math.sin(ba2)*bl*t+rand(-7,7),rand(3,11)*(1-t*0.6),0,TAU);g.fill();}
  }
  for(i=0;i<90;i++){
    g.save();g.translate(rand(T,WW-T),rand(T,WH-T));g.rotate(rand(0,TAU));
    g.fillStyle='rgba(225,232,236,'+rand(0.3,0.6)+')';g.fillRect(-8,-11,16,22);
    g.fillStyle='rgba(60,70,80,0.5)';g.fillRect(-5,-7,10,1.5);g.fillRect(-5,-3,10,1.5);g.fillRect(-5,1,7,1.5);g.restore();
  }
  for(i=0;i<200;i++){g.fillStyle='rgba(0,0,0,'+rand(0.04,0.12)+')';g.beginPath();g.arc(rand(0,WW),rand(0,WH),rand(8,46),0,TAU);g.fill();}
  // breached vents
  vents.forEach(function(vn){
    g.save();g.translate(vn.x,vn.y);
    g.save();g.beginPath();g.rect(-56,-56,112,112);g.clip();
    g.fillStyle='#1a1608';g.fillRect(-56,-56,112,112);
    g.strokeStyle='rgba(240,180,30,0.55)';g.lineWidth=9;g.beginPath();
    for(var q=-160;q<160;q+=28){g.moveTo(q,-60);g.lineTo(q+112,60);}
    g.stroke();g.restore();
    g.fillStyle='#020405';g.fillRect(-34,-34,68,68);
    g.strokeStyle='#3c4d5c';g.lineWidth=3;g.strokeRect(-34,-34,68,68);
    g.strokeStyle='#243240';g.lineWidth=4;g.beginPath();
    for(var s2=-24;s2<=24;s2+=12){g.moveTo(-30,s2);g.lineTo(30+rand(-14,0),s2+rand(-5,5));}
    g.stroke();
    for(var q2=0;q2<14;q2++){g.fillStyle='rgba(88,214,42,'+rand(0.2,0.5)+')';g.beginPath();g.arc(rand(-60,60),rand(-60,60),rand(2,9),0,TAU);g.fill();}
    g.restore();
  });
  // ----- walls and lab fixtures -----
  wallRects.forEach(function(w){
    var X=w.x,Y=w.y,Wd=w.w,Hd=w.h,horiz=Wd>=Hd,cx=X+Wd/2,cy=Y+Hd/2;
    if(drawCaveWall(g,w,X,Y,Wd,Hd))return;
    if(w.kind==='border'){
      g.fillStyle='#12171c';g.fillRect(X,Y,Wd,Hd);
      g.fillStyle='#2a343e';g.fillRect(X+5,Y+5,Wd-10,Hd-10);
      g.strokeStyle='rgba(0,0,0,0.45)';g.lineWidth=2;g.beginPath();
      if(horiz)for(k=X+T;k<X+Wd;k+=T){g.moveTo(k,Y+5);g.lineTo(k,Y+Hd-5);}
      else for(k=Y+T;k<Y+Hd;k+=T){g.moveTo(X+5,k);g.lineTo(X+Wd-5,k);}
      g.stroke();
      g.strokeStyle='#4a5a68';g.lineWidth=7;g.beginPath();
      if(horiz){g.moveTo(X+8,cy-10);g.lineTo(X+Wd-8,cy-10);}else{g.moveTo(cx-10,Y+8);g.lineTo(cx-10,Y+Hd-8);}
      g.stroke();
      g.strokeStyle='#8a5a2a';g.lineWidth=4;g.beginPath();
      if(horiz){g.moveTo(X+8,cy+12);g.lineTo(X+Wd-8,cy+12);}else{g.moveTo(cx+12,Y+8);g.lineTo(cx+12,Y+Hd-8);}
      g.stroke();
    }else if(w.kind==='glass'){
      g.fillStyle='rgba(0,0,0,0.35)';g.fillRect(X+5,Y+7,Wd,Hd);
      g.fillStyle='#8a98a5';g.fillRect(X,Y,Wd,Hd);
      g.fillStyle='#0c151c';if(horiz)g.fillRect(X+8,Y+17,Wd-16,Hd-34);else g.fillRect(X+17,Y+8,Wd-34,Hd-16);
      g.fillStyle='rgba(110,215,245,0.42)';if(horiz)g.fillRect(X+8,Y+17,Wd-16,Hd-34);else g.fillRect(X+17,Y+8,Wd-34,Hd-16);
      g.fillStyle='rgba(255,255,255,0.4)';if(horiz)g.fillRect(X+8,Y+19,Wd-16,3);else g.fillRect(X+19,Y+8,3,Hd-16);
      g.fillStyle='#5c6a76';
      if(horiz)for(k=X;k<=X+Wd;k+=T)g.fillRect(k-4,Y,8,Hd);else for(k=Y;k<=Y+Hd;k+=T)g.fillRect(X,k-4,Wd,8);
      g.strokeStyle='#3a4650';g.lineWidth=2;g.strokeRect(X+1,Y+1,Wd-2,Hd-2);
      g.fillStyle='rgba(240,200,50,0.5)';
      if(horiz){for(k=0;k<Wd;k+=24){g.fillRect(X+k,Y-7,12,5);g.fillRect(X+k,Y+Hd+2,12,5);}}
      else{for(k=0;k<Hd;k+=24){g.fillRect(X-7,Y+k,5,12);g.fillRect(X+Wd+2,Y+k,5,12);}}
    }else if(w.kind==='tank'){
      var broken=w.n%2===1;w.broken=broken;
      g.fillStyle='rgba(0,0,0,0.35)';g.fillRect(X+6,Y+8,Wd,Hd);
      g.fillStyle='#1c242b';g.fillRect(X,Y,Wd,Hd);
      g.strokeStyle='rgba(240,200,50,0.6)';g.lineWidth=4;g.setLineDash([12,10]);g.strokeRect(X+4,Y+4,Wd-8,Hd-8);g.setLineDash([]);
      g.fillStyle='#06100c';g.beginPath();g.arc(cx,cy,50,0,TAU);g.fill();
      if(!broken){
        var gr=g.createRadialGradient(cx-10,cy-10,4,cx,cy,50);
        gr.addColorStop(0,'rgba(170,255,190,0.75)');gr.addColorStop(1,'rgba(20,130,70,0.75)');
        g.fillStyle=gr;g.beginPath();g.arc(cx,cy,46,0,TAU);g.fill();
        g.fillStyle='rgba(4,24,12,0.8)';g.beginPath();g.ellipse(cx+2,cy+2,24,17,0.6,0,TAU);g.fill();
        g.beginPath();g.arc(cx+17,cy-10,10,0,TAU);g.fill();
        g.strokeStyle='rgba(4,24,12,0.8)';g.lineWidth=4;g.beginPath();g.moveTo(cx-18,cy+10);g.quadraticCurveTo(cx-34,cy+20,cx-24,cy+32);
        g.moveTo(cx-4,cy+16);g.lineTo(cx-8,cy+34);g.moveTo(cx+10,cy+16);g.lineTo(cx+16,cy+32);g.stroke();
        g.fillStyle='rgba(255,255,255,0.3)';g.beginPath();g.ellipse(cx-20,cy-22,14,7,-0.7,0,TAU);g.fill();
      }else{
        for(k=0;k<16;k++){g.fillStyle='rgba(88,214,42,'+rand(0.3,0.6)+')';g.beginPath();g.arc(cx+rand(-40,40),cy+rand(-40,40),rand(3,11),0,TAU);g.fill();}
        g.fillStyle='rgba(150,225,245,0.55)';
        for(k=0;k<22;k++){var sa=rand(0,TAU),sd=rand(30,112),px2=cx+Math.cos(sa)*sd,py2=cy+Math.sin(sa)*sd;
          g.beginPath();g.moveTo(px2,py2);g.lineTo(px2+rand(-9,9),py2+rand(-9,9));g.lineTo(px2+rand(-9,9),py2+rand(-9,9));g.fill();}
        for(k=0;k<30;k++){var ta=rand(0,TAU),td=rand(55,150);g.fillStyle='rgba(88,214,42,'+rand(0.15,0.4)+')';g.beginPath();g.arc(cx+Math.cos(ta)*td,cy+Math.sin(ta)*td,rand(2,9),0,TAU);g.fill();}
      }
      g.strokeStyle='#9fb2bf';g.lineWidth=6;
      if(broken){g.beginPath();g.arc(cx,cy,50,0.4,2.2);g.stroke();g.beginPath();g.arc(cx,cy,50,3.3,5.6);g.stroke();}
      else{g.beginPath();g.arc(cx,cy,50,0,TAU);g.stroke();}
    }else if(w.kind==='rack'){
      g.fillStyle='rgba(0,0,0,0.35)';g.fillRect(X+5,Y+7,Wd,Hd);
      g.fillStyle='#0d1216';g.fillRect(X,Y,Wd,Hd);
      g.strokeStyle='#4a5a68';g.lineWidth=3;g.strokeRect(X+2,Y+2,Wd-4,Hd-4);
      g.strokeStyle='#232c34';g.lineWidth=2;g.beginPath();for(k=12;k<Hd-6;k+=8){g.moveTo(X+8,Y+k);g.lineTo(X+Wd-8,Y+k);}g.stroke();
      g.strokeStyle='rgba(15,20,24,0.9)';g.lineWidth=4;g.beginPath();
      g.moveTo(cx,cy);g.bezierCurveTo(cx+rand(-120,120),cy+rand(60,140),cx+rand(-160,160),cy+rand(-40,160),cx+rand(-200,200),cy+rand(120,220));g.stroke();
    }else if(w.kind==='resin'||w.kind==='eggs'){
      g.fillStyle='rgba(0,0,0,0.4)';g.beginPath();g.ellipse(cx+6,cy+8,Wd*0.62,Hd*0.62,0,0,TAU);g.fill();
      g.fillStyle='#2a0c1c';g.beginPath();g.ellipse(cx,cy,Wd*0.6,Hd*0.6,0,0,TAU);g.fill();
      for(k=0;k<Math.max(6,Wd*Hd/600);k++){var ra=rand(0,TAU),rd=rand(0,0.42);g.fillStyle=pick(['#4a1430','#5e1a3c','#3a0e26','#6e2246']);g.beginPath();g.ellipse(cx+Math.cos(ra)*Wd*rd,cy+Math.sin(ra)*Hd*rd,rand(10,24),rand(8,18),rand(0,3),0,TAU);g.fill();}
      g.strokeStyle='rgba(255,90,150,0.35)';g.lineWidth=3;g.beginPath();
      for(k=0;k<5;k++){var va=rand(0,TAU);g.moveTo(cx,cy);g.quadraticCurveTo(cx+Math.cos(va+0.5)*Wd*0.3,cy+Math.sin(va+0.5)*Hd*0.3,cx+Math.cos(va)*Wd*0.55,cy+Math.sin(va)*Hd*0.55);}g.stroke();
      if(w.kind==='eggs'){var ne=Math.max(3,Math.round(Wd*Hd/1500));w.eggs=[];for(k=0;k<ne;k++){var ex=X+rand(18,Wd-18),ey=Y+rand(18,Hd-18);w.eggs.push([ex,ey,rand(11,16)]);
        g.fillStyle='#3a1a26';g.beginPath();g.ellipse(ex,ey,w.eggs[k][2]+3,w.eggs[k][2]*1.15+3,0,0,TAU);g.fill();g.fillStyle='#c86a90';g.beginPath();g.ellipse(ex,ey,w.eggs[k][2],w.eggs[k][2]*1.15,0,0,TAU);g.fill();
        g.strokeStyle='#5e1a3c';g.lineWidth=2;g.beginPath();g.moveTo(ex-6,ey-4);g.lineTo(ex,ey+2);g.lineTo(ex+6,ey-4);g.stroke();}}
    }else if(w.kind==='server'||w.kind==='cryo'||w.kind==='reactor'){
      g.fillStyle='rgba(0,0,0,0.35)';g.fillRect(X+5,Y+7,Wd,Hd);
      g.fillStyle=w.kind==='cryo'?'#1a2a34':w.kind==='reactor'?'#2a1e12':'#0d1216';g.fillRect(X,Y,Wd,Hd);
      g.strokeStyle=w.kind==='cryo'?'#7ad8ff':w.kind==='reactor'?'#ffb040':'#4a5a68';g.lineWidth=3;g.strokeRect(X+3,Y+3,Wd-6,Hd-6);
      if(w.kind==='cryo'){for(k=0;k<Math.floor(Wd/T)*Math.floor(Hd/T);k++){var px3=X+(k%Math.floor(Wd/T))*T+30,py3=Y+Math.floor(k/Math.floor(Wd/T))*T+30;
        g.fillStyle='#0a141a';g.beginPath();g.ellipse(px3,py3,20,26,0,0,TAU);g.fill();g.fillStyle='rgba(150,225,255,0.4)';g.beginPath();g.ellipse(px3,py3,17,23,0,0,TAU);g.fill();
        g.fillStyle='rgba(20,40,50,0.8)';g.beginPath();g.ellipse(px3,py3+2,7,12,0,0,TAU);g.fill();g.fillStyle='rgba(255,255,255,0.5)';g.fillRect(px3-10,py3-16,4,10);}}
      else if(w.kind==='reactor'){g.fillStyle='#120a04';g.beginPath();g.arc(cx,cy,Math.min(Wd,Hd)*0.42,0,TAU);g.fill();
        g.strokeStyle='#ffb040';g.lineWidth=5;g.beginPath();g.arc(cx,cy,Math.min(Wd,Hd)*0.42,0,TAU);g.stroke();
        for(k=0;k<8;k++){var ra2=k*TAU/8;g.fillStyle=k%2?'#ffb040':'#2a1e12';g.beginPath();g.moveTo(cx,cy);g.arc(cx,cy,Math.min(Wd,Hd)*0.3,ra2,ra2+TAU/8);g.fill();}}
      else{g.strokeStyle='#232c34';g.lineWidth=2;g.beginPath();for(k=10;k<Hd-6;k+=8){g.moveTo(X+8,Y+k);g.lineTo(X+Wd-8,Y+k);}g.stroke();}
    }else if(w.kind==='bench'){
      g.fillStyle='rgba(0,0,0,0.35)';g.fillRect(X+5,Y+7,Wd,Hd);
      g.fillStyle='#5c6a76';g.fillRect(X,Y,Wd,Hd);
      g.fillStyle='#b9c4cc';g.fillRect(X+4,Y+4,Wd-8,Hd-8);
      g.fillStyle='#1a2026';g.fillRect(X+10,Y+12,40,30);g.fillStyle='#39434c';g.fillRect(X+16,Y+46,28,7);
      var fc=['#5dff8a','#5ac8ff','#ff7ad0','#ffd76a'];
      for(k=0;k<5;k++){g.fillStyle='rgba(255,255,255,0.75)';g.beginPath();g.arc(X+16+(k%2)*24,Y+76+k*13,7,0,TAU);g.fill();
        g.fillStyle=fc[k%4];g.beginPath();g.arc(X+16+(k%2)*24,Y+76+k*13,4.5,0,TAU);g.fill();}
      g.fillStyle='#2a333b';g.beginPath();g.arc(cx,Y+Hd-26,13,0,TAU);g.fill();g.fillStyle='#8a98a5';g.beginPath();g.arc(cx,Y+Hd-26,6,0,TAU);g.fill();
      g.strokeStyle='#3a4650';g.lineWidth=2;g.strokeRect(X+1,Y+1,Wd-2,Hd-2);
    }
  });
  if(MAP.cave)bakeCave(g);
  // lit trim where the outer wall meets the floor
  if(!MAP.cave){g.strokeStyle='rgba(120,215,240,0.5)';g.lineWidth=3;g.strokeRect(T+1.5,T+1.5,WW-2*T-3,WH-2*T-3);}
  // sealed blast doors
  g.textAlign='center';g.textBaseline='middle';
  DOORS.forEach(function(d){
    var dw=d.h?4*T:T-8,dh=d.h?T-8:4*T,x0=d.x-dw/2,y0=d.y-dh/2;
    g.save();g.beginPath();g.rect(x0,y0,dw,dh);g.clip();
    g.fillStyle='#16181a';g.fillRect(x0,y0,dw,dh);
    g.strokeStyle='#d8aa20';g.lineWidth=14;g.beginPath();
    for(k=-300;k<300;k+=40){g.moveTo(d.x+k,d.y-160);g.lineTo(d.x+k+320,d.y+160);}
    g.stroke();g.restore();
    g.strokeStyle='#0a0c0e';g.lineWidth=5;g.strokeRect(x0,y0,dw,dh);
    g.beginPath();if(d.h){g.moveTo(d.x,y0);g.lineTo(d.x,y0+dh);}else{g.moveTo(x0,d.y);g.lineTo(x0+dw,d.y);}g.stroke();
    var fx=d.h?d.x:(d.x<WW/2?d.x+T+34:d.x-T-34),fy=d.h?(d.y<WH/2?d.y+T+4:d.y-T-4):d.y;
    g.save();g.translate(fx,fy);if(!d.h)g.rotate(d.x<WW/2?Math.PI/2:-Math.PI/2);
    g.font='bold 30px "Consolas","Courier New",monospace';g.fillStyle=d.exit?'rgba(255,200,60,0.6)':'rgba(255,70,60,0.6)';g.fillText(d.exit?'EXIT':'LOCKDOWN',0,0);
    g.font='bold 13px "Consolas","Courier New",monospace';g.fillStyle=d.exit?'rgba(255,200,60,0.5)':'rgba(255,70,60,0.5)';g.fillText(d.exit?'OPENS WHEN THE ROOM IS CLEAR':d.entry?'SEALED BEHIND YOU':'EXIT SEALED - NO WAY OUT',0,26);
    g.restore();
  });
}
function drawLabFx(){
  var i,k,w;
  ctx.globalCompositeOperation='lighter';
  for(i=0;i<FLICK.length;i++){
    var f=FLICK[i];if(!onScreen(f.x,f.y,220))continue;
    var n=Math.sin(stateT*13+i*7)+Math.sin(stateT*31+i*3);
    ctx.globalAlpha=n>1.1?0.02:0.2+0.04*Math.sin(stateT*50+i);ctx.drawImage(SPR_W,f.x-210,f.y-210,420,420);
  }
  for(i=0;i<DOORS.length;i++){
    var d=DOORS[i];if(!onScreen(d.x,d.y,260))continue;
    var dop=d.exit&&story&&story.exitOpen;
    ctx.globalAlpha=0.3+0.3*Math.sin(stateT*(dop?7:4)+i);ctx.drawImage(dop?SPR_G:SPR_R,d.x-170,d.y-170,340,340);
  }
  for(i=0;i<wallRects.length;i++){
    w=wallRects[i];if(w.kind!=='tank'||w.broken)continue;
    var cx=w.x+w.w/2,cy=w.y+w.h/2;if(!onScreen(cx,cy,180))continue;
    ctx.globalAlpha=0.3+0.12*Math.sin(stateT*2+i);ctx.drawImage(SPR_G,cx-130,cy-130,260,260);
  }
  ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  for(i=0;i<DOORS.length;i++){var dd=DOORS[i];if(!(dd.exit&&story&&story.exitOpen)||!onScreen(dd.x,dd.y,200))continue;
    var dw=dd.h?4*T:T-8,dh=dd.h?T-8:4*T;ctx.fillStyle='rgba(10,40,20,0.92)';ctx.fillRect(dd.x-dw/2,dd.y-dh/2,dw,dh);
    ctx.strokeStyle='#5dff8a';ctx.lineWidth=3;ctx.strokeRect(dd.x-dw/2,dd.y-dh/2,dw,dh);
    for(k=0;k<3;k++){var ck=((stateT*1.5+k/3)%1);ctx.globalAlpha=1-ck;ctx.fillStyle='#5dff8a';var ax=dd.x-(dd.x<WW/2?-1:1)*(60+ck*-90)-(dd.x<WW/2?0:0),ay=dd.y;
      ctx.beginPath();ctx.moveTo(dd.x-150+ck*110,ay-16);ctx.lineTo(dd.x-128+ck*110,ay);ctx.lineTo(dd.x-150+ck*110,ay+16);ctx.lineTo(dd.x-140+ck*110,ay);ctx.closePath();ctx.fill();}
    ctx.globalAlpha=1;txt('EXIT OPEN',dd.x-90,dd.y-50,16,'#5dff8a','center');}
  for(i=0;i<wallRects.length;i++){
    w=wallRects[i];
    if(w.kind==='border'||w.kind==='glass'||w.kind==='rock')continue;
    var x=w.x,y=w.y;if(!onScreen(x+w.w/2,y+w.h/2,140))continue;
    if(w.kind==='crystal'){ctx.globalCompositeOperation='lighter';ctx.globalAlpha=0.35+0.2*Math.sin(stateT*2.5+i);ctx.drawImage(SPR_W,x+w.w/2-w.w*1.4,y+w.h/2-w.h*1.4,w.w*2.8,w.h*2.8);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';continue;}
    if(w.kind==='tube'){ctx.fillStyle='rgba(56,232,255,'+(0.15+0.15*Math.sin(stateT*7+i))+')';ctx.beginPath();ctx.arc(x+w.w/2,y+w.h/2,w.w*0.36,0,TAU);ctx.fill();continue;}
    if(w.kind==='tank'){
      if(w.broken)continue;
      ctx.fillStyle='rgba(220,255,230,0.7)';
      for(k=0;k<5;k++){var t=(stateT*0.5+k*0.21+i*0.13)%1,ba=k*2.4+i;
        ctx.beginPath();ctx.arc(x+60+Math.cos(ba)*30*(1-t*0.5),y+60+Math.sin(ba)*30*(1-t*0.5)-t*8,1.5+t*3,0,TAU);ctx.fill();}
    }else if(w.kind==='server'){
      for(k=0;k<Math.floor(w.h/14);k++){var on2=Math.sin(stateT*(2+k*1.3)+i*5+k)>0;ctx.fillStyle=on2?(k%3===0?'#ff4a4a':k%3===1?'#5dff8a':'#5ac8ff'):'#1c242b';ctx.fillRect(x+w.w-14,y+8+k*14,5,4);ctx.fillRect(x+9,y+8+k*14,3,4);}
    }else if(w.kind==='rack'){
      for(k=0;k<8;k++){
        var on=Math.sin(stateT*(3+k*1.7)+i*5+k)>0;
        ctx.fillStyle=on?(k%3===0?'#ff4a4a':k%3===1?'#5dff8a':'#ffd76a'):'#1c242b';
        ctx.fillRect(x+12+(k%4)*10,y+16+Math.floor(k/4)*24,5,4);
      }
    }else if(w.kind==='bench'){
      var fl=Math.sin(stateT*9+i*3)>-0.92;
      ctx.fillStyle=fl?'rgba(70,200,255,0.9)':'rgba(20,50,70,0.9)';ctx.fillRect(x+13,y+15,34,24);
      if(fl){ctx.fillStyle='rgba(255,255,255,0.75)';var sy=(stateT*14+i*9)%20;ctx.fillRect(x+15,y+17+sy,22,2);ctx.fillRect(x+15,y+19,14,2);}
    }
  }
}
var mmC=document.createElement('canvas');mmC.width=160;mmC.height=120;
function bakeMini(){
  var g=mmC.getContext('2d');g.fillStyle='rgba(8,16,22,0.9)';g.fillRect(0,0,mmC.width,mmC.height);
  g.fillStyle='#4a6074';
  for(var y=0;y<MH;y++)for(var x=0;x<MW;x++)if(solid[y*MW+x]===1)g.fillRect(x*MS,y*MS,MS+0.5,MS+0.5);
  g.fillStyle='#6aff3a';vents.forEach(function(v){g.fillRect(v.tx*MS,v.ty*MS,MS,MS);});
  g.fillStyle='#ffd76a';DOORS.forEach(function(d){if(d.exit)g.fillRect(d.x/T*MS-MS*1.5,d.y/T*MS-MS*1.5,MS*3,MS*3);});
}
var BLOODS=['#3fae1e','#58d62a','#2f8a17','#7af03c','#46c224'];
function splat(x,y,size,dx,dy){
  var n=Math.floor(4+size*3);
  for(var i=0;i<n;i++){
    var a=rand(0,TAU),d=rand(0,size*9),st=rand(0,size*16);
    var qx=x+Math.cos(a)*d+(dx||0)*st,qy=y+Math.sin(a)*d+(dy||0)*st;
    if(qx<0||qy<0||qx>=WW||qy>=WH||solid[Math.floor(qy/T)*MW+Math.floor(qx/T)]===1)continue;
    decG.globalAlpha=rand(0.3,0.75);decG.fillStyle=pick(BLOODS);
    decG.beginPath();decG.arc(qx,qy,rand(1.5,1.5+size*4.2),0,TAU);decG.fill();
  }
  decG.globalAlpha=1;
}
function scorch(x,y,r){
  decG.globalAlpha=0.35;decG.fillStyle='#000';decG.beginPath();decG.arc(x,y,r,0,TAU);decG.fill();decG.globalAlpha=1;
}

