function startGame(){story=null;if(MAP!==LAB)buildMap(LAB);resetGame();state='play';stateT=0;netStart('endless');startWave(1);}
function isBossWave(n){return n===10||n===20||(n>20&&n%5===0);}
function bossType(n){return n===10?'queen':n%10===0?'zero':'queen';}
function isBoss(e){return e.type==='queen'||e.type==='zero';}
var ELITE=['phantom','bulwark','splitter','mender','tunneler'];
var INTRO={11:'NEW THREAT: PHANTOM - INVISIBLE UNTIL IT IS CLOSE',12:'NEW THREAT: BULWARK - ARMORED FRONT, HIT IT FROM BEHIND',13:'NEW THREAT: SPLITTER - BURSTS INTO MITES',14:'NEW THREAT: MENDER - HEALS AND HASTES THE SWARM, KILL IT FIRST',15:'NEW THREAT: TUNNELER - BURROWS UNDER YOU'};
function buildWave(n){
  var mend=0,list=[],count=n===10?46:n===20?50:n>10?Math.min(96,56+(n-10)*4):10+n*6;
  for(var i=0;i<count;i++){
    var r=Math.random(),t='crawler';
    if(r<0.10)t=n>=7?'spitter':'crawler';
    else if(r<0.20)t=n>=5?'brute':'crawler';
    else if(r<0.32)t=n>=4?'exploder':'crawler';
    else if(r<0.44)t=n>=3?'flyer':'crawler';
    else if(r<0.68)t=n>=2?'runner':'crawler';
    if(n>=11&&Math.random()<0.3){
      var tt=ELITE[Math.floor(Math.random()*Math.min(5,n-10))];
      if(tt==='mender'){if(mend>=3)tt='phantom';else mend++;}
      t=tt;
    }
    list.push(t);
  }
  if(n>=11&&n<=15)for(var q=0;q<(n===14?3-Math.min(3,mend):4);q++)list[q*4]=ELITE[n-11];
  return list;
}
function startWave(n){
  if(!story)netSend({t:'wave',n:n});
  wave=n;between=false;shopOpen=false;clearT=0;spawnQ=buildWave(n);spawnT=1.2;fusionCount=0;fusionCd=10;
  if(n>1)supplyDrop();
  if(bot)bot.hp=bot.maxHp;
  if(isBossWave(n)){
    var bst=vents[0],bd=-1;
    vents.forEach(function(v){var d=Math.hypot(v.x-player.x,v.y-player.y);if(d>bd){bd=d;bst=v;}});
    var bt=bossType(n);
    bossWarn={t:4.4,type:bt,vent:bst,n:n};spawnT=6;sirenT=0;banner.t=0;
  }else{banner.text='WAVE '+n+' INCOMING';banner.sub=INTRO[n]||'';banner.t=banner.sub?4.5:2.4;}
  sfx('wave');
}
function releaseBoss(){
  var w=bossWarn;bossWarn=null;
  queenRef=spawnEnemy(w.type,w.vent.x,w.vent.y);netSend({t:'boss',b:w.type});
  if(w.n>20){queenRef.hpScale=1+0.4*(w.n-20)/5;queenRef.hp=queenRef.maxHp=ET[w.type].hp*queenRef.hpScale*DIFFS[diff].hp;}
  banner.t=0;showBossCard(w.type==='zero'?'SPECIMEN ZERO':'THE HIVE QUEEN',w.type==='zero'?'THE FIRST OF THEM. THE LAST THING YOU SEE.':'MOTHER OF THE SWARM',w.type==='zero'?'#7af0ff':'#ff4a78',1,3.4);
  sfx('roar');shake(16);
  rings.push({x:w.vent.x,y:w.vent.y,r:260,life:0.6,max:0.6,col:w.type==='zero'?'#9af6ff':'#ff3a6a'});
  burst(w.vent.x,w.vent.y,60,['#39424a','#5a6772','#58d62a','#ffffff'],520,0.9,8);
}
function spawnEnemy(type,x,y){
  var fixed=type==='queen'||type==='zero'||type==='node',d=ET[type],hm=fixed?1:1+0.07*(wave-1),sm=fixed?1:1+0.012*(wave-1);
  var e={type:type,x:x,y:y,r:d.r,hp:d.hp*hm,maxHp:d.hp*hm,sp:d.sp*sm*rand(0.92,1.08),dmg:d.dmg,
    a:Math.atan2(player.y-y,player.x-x),ph:rand(0,TAU),kx:0,ky:0,flash:0,atk:0.3,dead:false,
    sh:rand(1,2.5),side:Math.random()<0.5?1:-1,mode:'chase',act:3,mt:0,ca:0,birth:4,burn:0,near:false,phz:1,slamCd:2.5,chain:0,st:0,sa:0,trail:0,hidden:false,shield:false,shieldStage:0,stun:0,ba:0,bdir:1,sum:6,farT:0,closeT:0,hideT:0,react:1.5,swCd:2,z:0,dying:0,dyingMax:1,final:false,lx:0,ly:0,lsx:0,lsy:0,spin:0,tb:false,tbT:rand(0,0.4),tauntT:0,vis:0,reveal:0,heal:null,blockT:0};
  e.hp=e.maxHp=e.hp*DIFFS[diff].hp;e.stage=1;e.fade=1;e.wing=0;
  if(type==='brute')sfx('growl');else if(type!=='node')sfx('screech');
  enemies.push(e);return e;
}

/* ---------- collision + pathing ---------- */
function collide(e,smash){
  var r=e.r;
  var x0=Math.max(0,Math.floor((e.x-r)/T)),x1=Math.min(MW-1,Math.floor((e.x+r)/T));
  var y0=Math.max(0,Math.floor((e.y-r)/T)),y1=Math.min(MH-1,Math.floor((e.y+r)/T));
  for(var ty=y0;ty<=y1;ty++)for(var tx=x0;tx<=x1;tx++){
    var s=solid[ty*MW+tx];if(!s)continue;
    var rx,ry,rw,rh;
    if(s===1){rx=tx*T;ry=ty*T;rw=T;rh=T;}
    else{var c=crateAt[ty*MW+tx];if(!c)continue;rx=c.x;ry=c.y;rw=c.w;rh=c.h;}
    var cx=clamp(e.x,rx,rx+rw),cy=clamp(e.y,ry,ry+rh),dx=e.x-cx,dy=e.y-cy,d2=dx*dx+dy*dy;
    if(d2<r*r){
      if(s===2&&smash){breakCrate(crateAt[ty*MW+tx]);continue;}
      if(d2>1e-6){var d=Math.sqrt(d2);e.x+=dx/d*(r-d);e.y+=dy/d*(r-d);}
      else{
        var l=e.x-rx,ri=rx+rw-e.x,t=e.y-ry,b=ry+rh-e.y,m=Math.min(l,ri,t,b);
        if(m===l)e.x=rx-r;else if(m===ri)e.x=rx+rw+r;else if(m===t)e.y=ry-r;else e.y=ry+rh+r;
      }
    }
  }
  e.x=clamp(e.x,T+r,WW-T-r);e.y=clamp(e.y,T+r,WH-T-r);
}
function computeFlow(){
  flow.fill(-1);
  var px=clamp(Math.floor(player.x/T),0,MW-1),py=clamp(Math.floor(player.y/T),0,MH-1);
  var h=0,t=0,i=py*MW+px;flow[i]=0;fq[t++]=i;
  while(h<t){
    i=fq[h++];var x=i%MW,y=(i-x)/MW,d=flow[i]+1,j;
    if(x>0){j=i-1;if(!solid[j]&&flow[j]<0){flow[j]=d;fq[t++]=j;}}
    if(x<MW-1){j=i+1;if(!solid[j]&&flow[j]<0){flow[j]=d;fq[t++]=j;}}
    if(y>0){j=i-MW;if(!solid[j]&&flow[j]<0){flow[j]=d;fq[t++]=j;}}
    if(y<MH-1){j=i+MW;if(!solid[j]&&flow[j]<0){flow[j]=d;fq[t++]=j;}}
  }
}
function steer(e){
  var tx=clamp(Math.floor(e.x/T),0,MW-1),ty=clamp(Math.floor(e.y/T),0,MH-1),d=flow[ty*MW+tx];
  var gx=player.x,gy=player.y;
  if(d>2){
    var best=d,bx=tx,by=ty;
    for(var oy=-1;oy<=1;oy++)for(var ox=-1;ox<=1;ox++){
      if(!ox&&!oy)continue;
      var nx=tx+ox,ny=ty+oy;if(nx<0||ny<0||nx>=MW||ny>=MH)continue;
      var fd=flow[ny*MW+nx];if(fd<0)continue;
      if(ox&&oy&&(flow[ty*MW+nx]<0||flow[ny*MW+tx]<0))continue;
      if(fd<best){best=fd;bx=nx;by=ny;}
    }
    gx=(bx+0.5)*T;gy=(by+0.5)*T;
  }
  return Math.atan2(gy-e.y,gx-e.x);
}

/* ---------- combat bot ---------- */
function botCap(){return botStage===1?4:6;}
function botMaxHp(){return botStage===1?50+bl.hp*25:140+bl.hp*30;}
function botSpeed(){return (botStage===1?250:275)+bl.spd*40;}
function botDps(){return Math.round((botStage===1?30+bl.dmg*10:(9+bl.dmg*1.5)*6)*(perkOn('bot')?1.5:1));}
function spawnBot(){
  bot={x:player.x-30,y:player.y+30,r:botStage===1?11:12,hp:botMaxHp(),maxHp:botMaxHp(),a:0,fire:0,cool:1,tick:0,target:null,flash:0,bob:0,
    orb:1,orbT:2,decoyT:0,decoyCd:3,inv:0,dodgeCd:0,dodgeT:0,ddx:0,ddy:0,cd:0,mag:24,rl:0,walk:0,stuck:0,mf:0};
  botOwned=true;sfx('botup');floatTxt(player.x,player.y-34,'COMBAT BOT ONLINE','#7af0ff');
}
function botHurt(d){
  if(!bot||bot.inv>0)return;
  bot.hp-=d;bot.flash=0.1;sfx('bothit');burst(bot.x,bot.y,4,['#7af0ff','#ffd76a'],160,0.3,3);
  if(bot.hp<=0){
    burst(bot.x,bot.y,26,['#7af0ff','#ffd76a','#ffffff','#39424a'],340,0.6,5);
    rings.push({x:bot.x,y:bot.y,r:60,life:0.3,max:0.3,col:'#7af0ff'});scorch(bot.x,bot.y,20);
    floatTxt(bot.x,bot.y-20,'BOT DESTROYED - REBUILD IN ARMORY','#ff6a5a');sfx('botdie');shake(5);bot=null;
  }
}
function startDecoy(){
  var b=bot;if(!b||b.decoyT>0||b.decoyCd>0)return false;
  b.decoyT=(botStage===1?3:4)*(perkOn('bot')?1.5:1);sfx('decoy');floatTxt(b.x,b.y-28,'DECOY!','#ffd76a');
  rings.push({x:b.x,y:b.y,r:300,life:0.5,max:0.5,col:'#ffd76a'});
  for(var i=0;i<enemies.length;i++){
    var e=enemies[i];if(isBoss(e)||e.type==='node')continue;
    if(Math.hypot(e.x-b.x,e.y-b.y)<640||Math.hypot(e.x-player.x,e.y-player.y)<440){e.tauntT=b.decoyT;e.tbT=0;}
  }
  return true;
}
function updateBot(){
  var b=bot,i,e,d;
  b.bob+=DT*6;if(b.flash>0)b.flash-=DT;if(b.inv>0)b.inv-=DT;if(b.dodgeCd>0)b.dodgeCd-=DT;if(b.mf>0)b.mf-=DT;
  // sense the fight
  var near=null,nd=430,threat=0,crowd=0,cx=0,cy=0,cn=0,closest=null,cd0=1e9;
  for(i=0;i<enemies.length;i++){
    e=enemies[i];if(e.dead||e.hidden||e.dying>0)continue;
    d=Math.hypot(e.x-b.x,e.y-b.y);
    if(d<e.r+110)threat++;
    if(d<320){cx+=e.x;cy+=e.y;cn++;}
    if(d<cd0){cd0=d;closest=e;}
    if(Math.hypot(e.x-player.x,e.y-player.y)<190)crowd++;
    if(!e.shield&&!(e.type==='phantom'&&e.vis<0.4)&&d<nd&&beamLen(b.x,b.y,Math.atan2(e.y-b.y,e.x-b.x),d)>=d-14){nd=d;near=e;}
  }
  // decoy: triggers by itself when the player is in trouble
  if(b.decoyT>0){b.decoyT-=DT;if(b.decoyT<=0)b.decoyCd=botStage===1?10:8;}
  else{
    if(b.decoyCd>0)b.decoyCd-=DT;
    if(b.decoyCd<=0&&enemies.length&&(player.hp<player.maxHp*0.4||crowd>=6))startDecoy();
  }
  // stage 2 sidestep
  if(botStage===2&&b.dodgeT<=0&&b.dodgeCd<=0&&closest&&cd0<closest.r+b.r+34){
    var ax0=b.x-closest.x,ay0=b.y-closest.y,al0=Math.hypot(ax0,ay0)||1;
    b.ddx=ax0/al0-ay0/al0*0.6*b.orb;b.ddy=ay0/al0+ax0/al0*0.6*b.orb;b.dodgeT=0.16;b.dodgeCd=2.4;b.inv=0.3;sfx('dash');
  }
  // movement
  var mvx=0,mvy=0,spd=botSpeed(),pdx=player.x-b.x,pdy=player.y-b.y,pd=Math.hypot(pdx,pdy)||1;
  if(b.dodgeT>0){b.dodgeT-=DT;mvx=b.ddx;mvy=b.ddy;spd*=3;part(b.x,b.y,0,0,0.18,'#ffb060',9,1);}
  else if(b.decoyT>0){
    if(cn){var ax=b.x-cx/cn,ay=b.y-cy/cn,al=Math.hypot(ax,ay)||1;mvx=ax/al;mvy=ay/al;}
    mvx-=pdx/pd*0.7;mvy-=pdy/pd*0.7;
    var wl=Math.hypot(mvx,mvy)||1,wx=-mvy/wl,wy=mvx/wl;mvx+=wx*0.5*b.orb;mvy+=wy*0.5*b.orb;
    spd*=1.25;
    if(pd>640){mvx=pdx/pd;mvy=pdy/pd;}
  }else if(near){
    var nx=(near.x-b.x)/nd,ny=(near.y-b.y)/nd,rad=clamp((nd-(botStage===1?170:210))/70,-1,1);
    if(threat>=3)rad=-1;
    mvx=nx*rad-ny*0.85*b.orb;mvy=ny*rad+nx*0.85*b.orb;
    if(pd>470){mvx=pdx/pd;mvy=pdy/pd;}
  }else if(closest&&cd0<520&&pd<420){mvx=(closest.x-b.x)/cd0;mvy=(closest.y-b.y)/cd0;}
  else if(pd>120){mvx=pdx/pd;mvy=pdy/pd;if(pd>400)spd*=1.5;}
  var ml=Math.hypot(mvx,mvy);
  if(ml>0.05){
    var ox=b.x,oy=b.y;b.x+=mvx/ml*spd*DT;b.y+=mvy/ml*spd*DT;collide(b,false);b.walk+=DT*14;
    if(Math.hypot(b.x-ox,b.y-oy)<spd*DT*0.35){b.stuck+=DT;if(b.stuck>0.25){b.orb=-b.orb;b.stuck=0;}}else b.stuck=0;
    if(!near)b.a=Math.atan2(mvy,mvx);
  }
  b.orbT-=DT;if(b.orbT<=0){b.orbT=rand(1.5,3.5);if(Math.random()<0.4)b.orb=-b.orb;}
  if(pd>950){b.x=player.x;b.y=player.y;}
  // weapons
  b.target=null;
  if(botStage===1){
    if(b.fire>0){
      b.fire-=DT;
      if(near){
        b.target=near;b.a=Math.atan2(near.y-b.y,near.x-b.x);b.tick-=DT;sfx('botlaser');
        if(b.tick<=0){b.tick=0.1;hitEnemy(near,botDps()*0.1,Math.cos(b.a),Math.sin(b.a),14);}
      }
      if(b.fire<=0)b.cool=3;
    }else{
      if(b.cool>0)b.cool-=DT;
      if(b.cool<=0&&near)b.fire=2.5;
    }
  }else if(near){
    b.a=Math.atan2(near.y-b.y,near.x-b.x);
    if(b.rl>0){b.rl-=DT;if(b.rl<=0)b.mag=24;}
    else{
      b.cd-=DT;
      if(b.cd<=0){
        b.cd=perkOn('bot')?1/9:1/6;b.mag--;b.mf=0.05;sfx('botgun');
        var ba=b.a+rand(-0.06,0.06),bx=b.x+Math.cos(b.a)*14,by=b.y+Math.sin(b.a)*14;
        bullets.push({type:'shot',x:bx,y:by,px:bx,py:by,vx:Math.cos(ba)*900,vy:Math.sin(ba)*900,life:0.6,dmg:9+bl.dmg*1.5,knock:50,col:'#ffb060'});
        if(b.mag<=0)b.rl=1.6;
      }
    }
  }else if(b.rl>0){b.rl-=DT;if(b.rl<=0)b.mag=24;}
}
function botMaxed(){return bl.dmg>=4&&bl.spd>=4&&bl.hp>=4;}
function botInfo(kind){
  if(kind==='botbuy')return {ok:true,cost:!botOwned?300:botStage===1?150:300,label:botOwned?'REBUILD COMBAT BOT (KEEPS UPGRADES AND STAGE)':'BUY COMBAT BOT - ROAMS, SHOOTS, DECOYS'};
  if(kind==='bevo')return {ok:true,cost:600,label:'EVOLVE TO STAGE 2 - TROOPER BOT (RIFLE, DODGE)'};
  var l=kind==='bdmg'?bl.dmg:kind==='bspd'?bl.spd:bl.hp,cap=botCap();
  return {ok:l<cap,cost:90+l*70,label:{bdmg:'DMG ',bspd:'SPEED ',bhp:'HP '}[kind]+l+'/'+cap};
}
function buyBot(kind){
  var inf=botInfo(kind);
  if(!inf.ok){sfx('deny');shopSay('ALREADY MAXED');return;}
  if(credits<inf.cost){sfx('deny');shopSay('NOT ENOUGH CREDITS');return;}
  credits-=inf.cost;sfx('buy');
  if(kind==='botbuy'){spawnBot();shopSay('COMBAT BOT ONLINE');}
  else if(kind==='bevo'){botStage=2;if(bot){bot.r=12;bot.maxHp=botMaxHp();bot.hp=bot.maxHp;}sfx('botup');shopSay('BOT EVOLVED: STAGE 2 TROOPER - UPGRADES NOW GO TO 6');}
  else if(kind==='bdmg'){bl.dmg++;shopSay('BOT DAMAGE UP');}
  else if(kind==='bspd'){bl.spd++;shopSay('BOT SPEED UP');}
  else{bl.hp++;if(bot){bot.maxHp=botMaxHp();bot.hp=bot.maxHp;}shopSay('BOT HEALTH UP');}
}
/* ---------- boss helpers ---------- */
function bossSense(e,dist,toP){
  e.farT=dist>560?e.farT+DT:0;e.closeT=dist<215?e.closeT+DT:0;
  e.hideT=beamLen(e.x,e.y,toP,dist)<dist-14?e.hideT+DT:0;
  if(e.react>0)e.react-=DT;if(e.swCd>0)e.swCd-=DT;if(e.spin>0)e.spin-=DT;
}
function lead(e,speed){
  var d=Math.hypot(player.x-e.x,player.y-e.y),t=Math.min(0.9,d/speed);
  return Math.atan2(player.y+player.vy*t-e.y,player.x+player.vx*t-e.x);
}
function bossThrow(e,count){
  var c=crates.filter(function(k){return !k.dead&&!k.shield&&Math.hypot(k.x+k.w/2-e.x,k.y+k.h/2-e.y)<540;});
  c.sort(function(a,b){return Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y);});
  for(var k=0;k<count;k++){
    var o=c[k];
    if(o){
      o.dead=true;var idx=o.ty*MW+o.tx;solid[idx]=0;crateAt[idx]=null;flowT=0;
      throws.push({state:'lift',x:o.x+o.w/2,y:o.y+o.h/2,z:0,t:0,lift:0.7+k*0.28,barrel:o.barrel,rubble:false,owner:e,tx:0,ty:0,sx:0,sy:0,dur:1,rot:rand(0,TAU)});
    }else{
      var a=rand(0,TAU);
      throws.push({state:'lift',x:e.x+Math.cos(a)*(e.r+30),y:e.y+Math.sin(a)*(e.r+30),z:0,t:0,lift:0.6+k*0.28,barrel:false,rubble:true,owner:e,tx:0,ty:0,sx:0,sy:0,dur:1,rot:rand(0,TAU)});
    }
  }
  sfx('growl');
}
function zRain(e,n){
  for(var i=0;i<n;i++){
    var tx=clamp(player.x+player.vx*0.12*i+rand(-160,160),T+30,WW-T-30),ty=clamp(player.y+player.vy*0.12*i+rand(-160,160),T+30,WH-T-30);
    throws.push({state:'fall',x:tx,y:ty,z:520,t:0,lift:0,barrel:false,rubble:true,owner:e,tx:tx,ty:ty,sx:tx,sy:ty,dur:0.95+i*0.17,rot:rand(0,TAU)});
  }
  sfx('roar');shake(8);
}
function impact(th){
  if(th.barrel){explode(th.tx,th.ty,135,160,25);return;}
  burst(th.tx,th.ty,16,th.rubble?['#5a6772','#39424a','#8a98a5']:['#aab4bc','#6a7680','#e8892a','#dfe6ea'],320,0.6,7);
  scorch(th.tx,th.ty,26);shake(5);sfx('crate');
  rings.push({x:th.tx,y:th.ty,r:75,life:0.25,max:0.25,col:'#ffb040'});
  if(Math.hypot(player.x-th.tx,player.y-th.ty)<72+player.r)hurt(th.rubble?20:24);
}
function qLeap(e){e.mode='leapwind';e.mt=0.4;sfx('growl');}
function zBurrow(e){e.mode='burrow';e.mt=1.6;e.hidden=true;e.burn=0;sfx('growl');burst(e.x,e.y,30,['#39424a','#232a30','#5a6772'],300,0.8,9);scorch(e.x,e.y,40);}
function startBossDeath(e){
  e.dying=1.15;e.dyingMax=1.15;e.hp=1;e.shield=false;e.hidden=false;e.z=0;e.mode='dying';e.burn=0;
  spawnQ=[];throws=[];acid=[];clearHazards();
  enemies.forEach(function(o){if(!o.dead&&o!==e)killEnemy(o,0,0);});
  sfx('die_'+e.type);shake(12);
}
/* ---------- boss stage 2: evolution ---------- */
var BOSS2={queen:{hp:5800,r:56,sp:118,dmg:38,name:'THE CRIMSON EMPRESS',sub:'THE QUEEN HAS ASCENDED',col:'#ff3a6a',rgb:'255,58,106'},
  zero:{hp:11000,r:46,sp:150,dmg:48,name:'ZERO : UNBOUND',sub:'ITS SHELL WAS THE ONLY THING HOLDING IT BACK',col:'#c08aff',rgb:'192,138,255'}};
var marks=[],lasers=[],shocks=[],holes=[],bossCard={t:0,max:1,name:'',sub:'',col:'#fff',stage:1};
function showBossCard(name,sub,col,stage,dur){bossCard={t:dur||3.4,max:dur||3.4,name:name,sub:sub,col:col,stage:stage};}
function clearHazards(){marks=[];lasers=[];shocks=[];holes=[];}
function startEvolve(e){
  netSend({t:'evolve',b:e.type});codexAdd(e.type,e.x,e.y);
  e.mode='evolve';e.mt=4.4;e.hp=1;e.hidden=false;e.z=0;e.shield=false;e.stun=0;e.burn=0;e.chain=0;e.spin=0;e.hbt=0;
  throws=[];acid=[];clearHazards();spawnQ=[];
  enemies.forEach(function(o){if(!o.dead&&o!==e&&!isBoss(o)){o.final=true;killEnemy(o,0,0);}});
  slowT=1.4;shake(16);sfx('roar');sfx('die_'+e.type);flashT=0.35;bossCard.t=0;
  if(story)say(e.type==='queen'?'She is... changing. Oh god. KEEP SHOOTING!':'It is shedding its shell!',4);
  banner.text=e.type==='queen'?'SHE IS NOT DEAD':'SPECIMEN ZERO IS CHANGING';banner.sub='SOMETHING WORSE IS COMING';banner.t=3.4;
}
function updateEvolve(e){
  e.mt-=DT;e.ph+=DT*(4+(4.4-e.mt)*3);var k=clamp(1-e.mt/4.4,0,1),B=BOSS2[e.type];
  e.r+=(B.r-e.r)*DT*0.25*k;
  if(Math.random()<0.6+k*0.4){var a=rand(0,TAU),d=rand(170,420);part(e.x+Math.cos(a)*d,e.y+Math.sin(a)*d,-Math.cos(a)*d*1.9,-Math.sin(a)*d*1.9,0.5,pick([B.col,'#ffffff',e.type==='queen'?'#ffd76a':'#9af6ff']),rand(3,7),1);}
  if(Math.random()<0.08+k*0.2){rings.push({x:e.x,y:e.y,r:e.r*(1.4+k),life:0.3,max:0.3,col:B.col});}
  shake(0.2+k*0.7);
  e.hbt-=DT;if(e.hbt<=0){e.hbt=0.75-k*0.45;sfx('heart');}
  if(!e.ev2&&e.mt<1.3){e.ev2=1;sfx('charge');}
  if(e.mt<=0)evolveNow(e);
}
function evolveNow(e){
  var B=BOSS2[e.type],sc=e.hpScale||1;
  e.stage=2;e.r=B.r;e.maxHp=e.hp=B.hp*sc*DIFFS[diff].hp;e.sp=B.sp;e.dmg=B.dmg;e.mode='chase';e.act=1.6;e.react=2;e.swCd=2;
  e.hideT=0;e.farT=0;e.closeT=0;e.sum=7;e.birth=7;e.slamCd=2;e.ev2=0;e.enr=0;e.fade=1;e.z=0;e.hidden=false;
  flashT=0.5;shake(18);sfx('bossboom');sfx('roar');sfx('evolve');slowT=0.9;
  rings.push({x:e.x,y:e.y,r:260,life:0.45,max:0.45,col:'#ffffff'});rings.push({x:e.x,y:e.y,r:480,life:0.8,max:0.8,col:B.col});rings.push({x:e.x,y:e.y,r:720,life:1.1,max:1.1,col:B.col});
  burst(e.x,e.y,140,[B.col,'#ffffff',e.type==='queen'?'#ffd76a':'#9af6ff','#39424a'],700,1.2,9);scorch(e.x,e.y,110);
  var d=Math.hypot(player.x-e.x,player.y-e.y)||1;if(d<320){player.x+=(player.x-e.x)/d*(330-d)*0.6;player.y+=(player.y-e.y)/d*(330-d)*0.6;collide(player,false);}
  banner.t=0;showBossCard(B.name,B.sub,B.col,2,3.6);
}
function q2Dive(e,n){e.mode='soar';e.mt=0.45;e.chain=n;e.lx=e.x;e.ly=e.y;sfx('growl');burst(e.x,e.y,24,['#ff3a6a','#39424a','#ffffff'],380,0.6,7);}
function q2Gust(e,toP){
  e.mode='cast';e.mt=0.7;sfx('roar');shake(9);
  rings.push({x:e.x,y:e.y,r:330,life:0.4,max:0.4,col:'#ff9ab0'});
  var d=Math.hypot(player.x-e.x,player.y-e.y)||1;
  if(d<360&&player.dash<=0){player.x+=(player.x-e.x)/d*170;player.y+=(player.y-e.y)/d*170;collide(player,false);hurt(12);}
  var gap=Math.floor(rand(4,20));
  for(var j=0;j<24;j++){if(Math.abs(j-gap)<=1)continue;spit(e.x,e.y,toP-1.1+j*2.2/23,360,13);}
  sfx('spit');
}
function acidRain(e,n){
  for(var i=0;i<n;i++){
    var x=clamp(player.x+player.vx*0.35+rand(-240,240),T+40,WW-T-40),y=clamp(player.y+player.vy*0.35+rand(-240,240),T+40,WH-T-40);
    if(i===0){x=player.x;y=player.y;}
    marks.push({x:x,y:y,r:64,t:1.05+i*0.07,max:1.05+i*0.07,dmg:17,col:'255,60,110',kind:'acid'});
  }
  sfx('roar');shake(6);
}
function queen2(e,dist,toP,dx,dy){
  var hk=e.hp/e.maxHp,en=hk<0.4,haste=en?0.68:1,sp=e.sp*(en?1.25:1),j;
  bossSense(e,dist,toP);e.wing+=DT*(e.z>0?15:5);
  if(en&&!e.enr){e.enr=1;showBossCard('THE EMPRESS SCREAMS','EVERY EGG IN THE NEST IS LISTENING','#ff3a6a',2,2.2);sfx('roar');shake(14);}
  if(e.mode==='chase'){
    e.act-=DT;e.birth-=DT;
    if(dist<240)sp*=0.45;
    if(e.birth<=0){
      e.birth=10*haste+2;
      if(enemies.length<48){
        for(j=0;j<(en?2:1);j++){var g=spawnEnemy('brute',e.x+rand(-60,60),e.y+rand(-60,60));g.age=6;}
        for(j=0;j<4;j++)spawnEnemy(j%2?'runner':'exploder',e.x+rand(-50,50),e.y+rand(-50,50));
        floatTxt(e.x,e.y-e.r-30,'ROYAL GUARD','#ff9ab0');sfx('roar');
      }
    }
    if(e.react<=0&&dashedT>0){e.react=2.1*haste+0.5;var la=lead(e,460);for(j=-3;j<=3;j++)spit(e.x,e.y,la+j*0.12,460,13);sfx('spit');}
    else if(e.hideT>1.6){e.hideT=0;q2Dive(e,1);}
    else if(e.farT>2.2){e.farT=0;q2Dive(e,2);}
    else if(e.closeT>0.9&&e.swCd<=0){e.swCd=3.2*haste+0.6;q2Gust(e,toP);}
    else if(e.act<=0){
      var r=Math.random();
      if(r<0.26)q2Dive(e,en?3:2);
      else if(r<0.44){acidRain(e,en?15:10);e.mode='cast';e.mt=0.9;}
      else if(r<0.62){e.mode='q2wind';e.mt=0.45;e.ca=lead(e,780);e.chain=en?3:2;sfx('roar');}
      else if(r<0.82){e.mode='sweep';e.mt=en?2.8:2.2;e.sa=toP;e.st=0;sfx('growl');}
      else q2Gust(e,toP);
    }
  }else if(e.mode==='cast'){sp=0;e.mt-=DT;if(e.mt<=0){e.mode='chase';e.act=rand(0.9,1.5)*haste;}}
  else if(e.mode==='soar'){
    sp=0;e.mt-=DT;e.z=Math.min(280,e.z+DT*700);e.hidden=e.z>70;e.lx=e.x;e.ly=e.y;
    if(e.mt<=0){e.mode='hunt';e.mt=0.9;}
  }else if(e.mode==='hunt'){
    sp=0;e.mt-=DT;var hs=Math.min(dist,560*DT);e.x+=dx/dist*hs;e.y+=dy/dist*hs;e.lx=e.x;e.ly=e.y;
    if(e.mt<=0){
      e.lsx=e.x;e.lsy=e.y;e.lx=clamp(player.x+player.vx*0.18,T+70,WW-T-70);e.ly=clamp(player.y+player.vy*0.18,T+70,WH-T-70);
      e.mode='dive';e.mt=0.3;sfx('dash');
    }
  }else if(e.mode==='dive'){
    sp=0;e.mt-=DT;var k=clamp(1-e.mt/0.3,0,1);e.x=e.lsx+(e.lx-e.lsx)*k;e.y=e.lsy+(e.ly-e.lsy)*k;e.z=280*(1-k*k);
    if(e.mt<=0){
      e.z=0;e.hidden=false;collide(e,true);
      rings.push({x:e.x,y:e.y,r:190,life:0.4,max:0.4,col:'#ff3a6a'});rings.push({x:e.x,y:e.y,r:320,life:0.6,max:0.6,col:'#ffd76a'});
      shake(16);sfx('boom');scorch(e.x,e.y,70);splat(e.x,e.y,2.5,0,0);burst(e.x,e.y,40,['#ff3a6a','#ffffff','#5a6772','#ffd76a'],520,0.6,7);
      var ld=Math.hypot(player.x-e.x,player.y-e.y)||1;
      if(ld<200){hurt(30);player.x+=(player.x-e.x)/ld*80;player.y+=(player.y-e.y)/ld*80;}
      for(j=0;j<14;j++)spit(e.x,e.y,j*TAU/14+e.ph,360,12);
      if(--e.chain>0){e.mode='soar';e.mt=0.2;}else{e.mode='chase';e.act=rand(1.2,1.8)*haste;}
    }
  }else if(e.mode==='q2wind'){sp=0;e.oang=e.ca;e.mt-=DT;e.x+=rand(-2,2);if(e.mt<=0){e.mode='q2charge';e.mt=0.55;}}
  else if(e.mode==='q2charge'){
    sp=800;e.oang=e.ca;e.a=e.ca;e.mt-=DT;e.trail-=DT;
    if(e.trail<=0){e.trail=0.06;spit(e.x,e.y,e.ca+Math.PI/2,140,11,1.3);spit(e.x,e.y,e.ca-Math.PI/2,140,11,1.3);}
    if(e.mt<=0){if(e.chain>0){e.chain--;e.mode='q2wind';e.mt=0.24;e.ca=lead(e,800);}else{e.mode='chase';e.act=rand(1.2,1.9)*haste;}}
  }else if(e.mode==='sweep'){
    sp*=0.25;e.mt-=DT;e.st-=DT;e.spin=0.2;
    if(e.st<=0){e.st=0.055;e.sa+=0.23;for(j=0;j<(en?4:3);j++)spit(e.x,e.y,e.sa+j*TAU/(en?4:3),330,11);sfx('spit');}
    if(e.mt<=0){e.mode='chase';e.act=rand(1.2,1.8)*haste;}
  }
  return sp;
}
function z2Blink(e,n){e.mode='blinkout';e.mt=0.3;e.chain=n;sfx('charge');}
function lattice(e,n){
  for(var i=0;i<n;i++){
    var a=i===0?Math.atan2(player.vy||0.01,player.vx||0.01)+Math.PI/2:pick([0,Math.PI/2,Math.PI/4,-Math.PI/4])+rand(-0.15,0.15);
    lasers.push({x:clamp(player.x+(i?rand(-300,300):0),T,WW-T),y:clamp(player.y+(i?rand(-300,300):0),T,WH-T),a:a,t:1.0+i*0.11,on:0.42,fired:0});
  }
  sfx('charge');
}
function singularity(e){holes.push({x:clamp(player.x+rand(-140,140),T+60,WW-T-60),y:clamp(player.y+rand(-140,140),T+60,WH-T-60),t:4,max:4,r:400});sfx('charge');sfx('growl');}
function shockwave(e,n){for(var i=0;i<n;i++)shocks.push({x:e.x,y:e.y,r:e.r,delay:i*0.6,sp:430,max:1100,hit:false});sfx('roar');shake(8);}
function zero2(e,dist,toP,dx,dy){
  var zk=e.hp/e.maxHp,en=zk<0.4,zh=en?0.7:1,sp=e.sp/zh,j;
  bossSense(e,dist,toP);
  if(en&&!e.enr){e.enr=1;showBossCard('ZERO IS UNRAVELLING','REALITY BENDS AROUND IT','#c08aff',2,2.2);sfx('roar');shake(14);}
  if(e.fade<1&&e.mode!=='blinkout'&&e.mode!=='blinkin')e.fade=Math.min(1,e.fade+DT*4);
  if(e.mode==='chase'){
    e.act-=DT;e.sum-=DT;
    if(e.sum<=0){e.sum=11*zh+3;if(enemies.length<44){for(j=0;j<(en?3:2);j++)spawnEnemy('phantom',e.x+rand(-70,70),e.y+rand(-70,70));floatTxt(e.x,e.y-e.r-30,'ECHOES','#c08aff');}}
    if(e.react<=0&&dashedT>0){e.react=2.6*zh+0.6;z2Blink(e,1);}
    else if(e.hideT>1.6||e.farT>2.2){e.hideT=0;e.farT=0;z2Blink(e,2);}
    else if(e.closeT>0.8&&e.swCd<=0){e.swCd=3.2*zh+0.5;shockwave(e,en?3:2);e.mode='cast';e.mt=0.8;}
    else if(e.act<=0){
      var r=Math.random();
      if(r<0.22)z2Blink(e,en?4:3);
      else if(r<0.42){lattice(e,en?8:6);e.mode='cast';e.mt=1.1;}
      else if(r<0.58&&!holes.length){singularity(e);e.mode='cast';e.mt=0.8;}
      else if(r<0.76){shockwave(e,en?3:2);e.mode='cast';e.mt=1;}
      else{e.mode='beamwind2';e.mt=0.85;e.bdir=Math.random()<0.5?1:-1;e.ba=toP-e.bdir*0.9;sfx('charge');}
    }
  }else if(e.mode==='cast'){sp=0;e.mt-=DT;if(e.mt<=0){e.mode='chase';e.act=rand(0.9,1.5)*zh;}}
  else if(e.mode==='blinkout'){
    sp=0;e.mt-=DT;e.fade=clamp(e.mt/0.3,0,1);
    if(e.mt<=0){
      burst(e.x,e.y,26,['#c08aff','#ffffff','#9af6ff'],360,0.5,5);
      var ok=false,tries=0,nx=e.x,ny=e.y;
      while(!ok&&tries++<20){var ba=player.a+Math.PI+rand(-0.9,0.9),bd=rand(130,190);nx=clamp(player.x+Math.cos(ba)*bd,T+e.r,WW-T-e.r);ny=clamp(player.y+Math.sin(ba)*bd,T+e.r,WH-T-e.r);ok=!solid[Math.floor(ny/T)*MW+Math.floor(nx/T)];}
      e.x=nx;e.y=ny;e.mode='blinkin';e.mt=0.42;e.fade=0;e.hidden=true;sfx('dash');
    }
  }else if(e.mode==='blinkin'){
    sp=0;e.mt-=DT;e.fade=1-clamp(e.mt/0.42,0,1);e.oang=toP;
    if(e.mt<=0){
      e.hidden=false;e.fade=1;collide(e,true);
      rings.push({x:e.x,y:e.y,r:170,life:0.35,max:0.35,col:'#c08aff'});shake(12);sfx('boom');
      burst(e.x,e.y,30,['#c08aff','#ffffff','#9af6ff'],460,0.5,6);
      if(dist<175)hurt(30);
      for(j=0;j<12;j++)spit(e.x,e.y,j*TAU/12,420,13);
      if(--e.chain>0){e.mode='blinkout';e.mt=0.24;}else{e.mode='chase';e.act=rand(1.1,1.7)*zh;}
    }
  }else if(e.mode==='beamwind2'){sp=0;e.oang=e.ba;e.a=e.ba;e.mt-=DT;if(e.mt<=0){e.mode='beam2';e.mt=en?2.8:2.3;}}
  else if(e.mode==='beam2'){
    sp=0;e.mt-=DT;e.ba+=e.bdir*1.3*DT*(en?1.2:1);e.oang=e.ba;e.a=e.ba;sfx('zbeam');if(Math.random()<0.4)shake(0.9);
    for(j=0;j<3;j++){
      var bang=e.ba+j*TAU/3,bc=Math.cos(bang),bsn=Math.sin(bang),bL=beamLen(e.x,e.y,bang,1400);
      var bt2=clamp(dx*bc+dy*bsn,0,bL),bqx=dx-bc*bt2,bqy=dy-bsn*bt2;
      if(bqx*bqx+bqy*bqy<(player.r+10)*(player.r+10))hurt(30);
    }
    if(e.mt<=0){e.mode='chase';e.act=rand(1.2,1.9)*zh;}
  }
  return sp;
}
function updateHazards(){
  var i,m,d;
  for(i=marks.length-1;i>=0;i--){m=marks[i];m.t-=DT;
    if(m.t<=0){marks.splice(i,1);
      rings.push({x:m.x,y:m.y,r:m.r,life:0.3,max:0.3,col:'#ff3a6a'});burst(m.x,m.y,14,['#ff3a6a','#c8ff3a','#ffffff'],300,0.45,5);splat(m.x,m.y,1.2,0,0);sfx('spit');shake(2);
      if(Math.hypot(player.x-m.x,player.y-m.y)<m.r+player.r*0.5)hurt(m.dmg*(skinOn('crimson')?0.5:1));}}
  for(i=lasers.length-1;i>=0;i--){m=lasers[i];
    if(m.t>0){m.t-=DT;continue;}
    if(!m.fired){m.fired=1;sfx('zbeam');shake(4);}
    m.on-=DT;
    var ca=Math.cos(m.a),sa=Math.sin(m.a),px=player.x-m.x,py=player.y-m.y;
    if(Math.abs(px*sa-py*ca)<player.r+12)hurt(26);
    if(m.on<=0)lasers.splice(i,1);}
  for(i=holes.length-1;i>=0;i--){m=holes[i];m.t-=DT;d=Math.hypot(player.x-m.x,player.y-m.y)||1;
    if(d<m.r&&player.dash<=0){var f=(1-d/m.r)*230+70;player.x-=(player.x-m.x)/d*f*DT;player.y-=(player.y-m.y)/d*f*DT;}
    if(Math.random()<0.8){var a=rand(0,TAU),r=rand(80,m.r);part(m.x+Math.cos(a)*r,m.y+Math.sin(a)*r,-Math.cos(a)*r*1.6+Math.sin(a)*120,-Math.sin(a)*r*1.6-Math.cos(a)*120,0.5,pick(['#c08aff','#ffffff','#5a2a9a']),4,0.97);}
    for(var j=0;j<acid.length;j++){var ac=acid[j],ad=Math.hypot(ac.x-m.x,ac.y-m.y)||1;if(ad<m.r){ac.vx-=(ac.x-m.x)/ad*300*DT;ac.vy-=(ac.y-m.y)/ad*300*DT;}}
    if(m.t<=0){holes.splice(i,1);rings.push({x:m.x,y:m.y,r:160,life:0.4,max:0.4,col:'#c08aff'});rings.push({x:m.x,y:m.y,r:300,life:0.6,max:0.6,col:'#ffffff'});
      burst(m.x,m.y,50,['#c08aff','#ffffff','#9af6ff'],520,0.7,6);shake(12);sfx('boom');if(d<165)hurt(34);}}
  for(i=shocks.length-1;i>=0;i--){m=shocks[i];
    if(m.delay>0){m.delay-=DT;if(m.delay<=0){sfx('boom');shake(6);}continue;}
    m.r+=m.sp*DT;d=Math.hypot(player.x-m.x,player.y-m.y);
    if(!m.hit&&Math.abs(d-m.r)<20){m.hit=true;hurt(24);}
    if(m.r>m.max)shocks.splice(i,1);}
}
function drawHazards(){
  var i,m,k;
  ctx.save();
  for(i=0;i<marks.length;i++){m=marks[i];k=1-m.t/m.max;
    ctx.fillStyle='rgba('+m.col+','+(0.08+k*0.2)+')';ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,TAU);ctx.fill();
    ctx.strokeStyle='rgba('+m.col+',0.9)';ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,TAU);ctx.stroke();
    ctx.beginPath();ctx.arc(m.x,m.y,m.r*k,0,TAU);ctx.stroke();
    if(m.t<0.45){var fz=m.t/0.45;ctx.fillStyle='rgba(200,255,60,0.9)';ctx.beginPath();ctx.arc(m.x,m.y-fz*520,7+3*(1-fz),0,TAU);ctx.fill();}}
  for(i=0;i<holes.length;i++){m=holes[i];k=m.t/m.max;
    ctx.fillStyle='rgba(60,10,90,0.18)';ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,TAU);ctx.fill();
    ctx.strokeStyle='rgba(192,138,255,0.5)';ctx.lineWidth=2;ctx.setLineDash([12,10]);ctx.beginPath();ctx.arc(m.x,m.y,m.r,stateT,stateT+TAU);ctx.stroke();ctx.setLineDash([]);
    for(var s2=0;s2<3;s2++){ctx.strokeStyle='rgba(192,138,255,'+(0.5-s2*0.12)+')';ctx.lineWidth=3;ctx.beginPath();ctx.arc(m.x,m.y,40+s2*26+((stateT*-60)%26+26)%26,stateT*3+s2,stateT*3+s2+4);ctx.stroke();}
    ctx.fillStyle='#000000';ctx.beginPath();ctx.arc(m.x,m.y,30+6*Math.sin(stateT*12),0,TAU);ctx.fill();
    ctx.strokeStyle='#ffffff';ctx.lineWidth=2;ctx.stroke();
    if(k<0.25){ctx.strokeStyle='rgba(255,255,255,0.9)';ctx.beginPath();ctx.arc(m.x,m.y,165*(1-k/0.25),0,TAU);ctx.stroke();}}
  for(i=0;i<shocks.length;i++){m=shocks[i];if(m.delay>0)continue;var sk=1-m.r/m.max;
    ctx.strokeStyle='rgba(192,138,255,'+(0.35+0.5*sk)+')';ctx.lineWidth=16;ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,TAU);ctx.stroke();
    ctx.strokeStyle='rgba(255,255,255,'+(0.6*sk+0.2)+')';ctx.lineWidth=4;ctx.stroke();}
  ctx.lineCap='round';
  for(i=0;i<lasers.length;i++){m=lasers[i];var L=3200,ca=Math.cos(m.a),sa=Math.sin(m.a);
    if(m.t>0){ctx.globalAlpha=0.35+0.35*Math.sin(stateT*40);ctx.strokeStyle='#c08aff';ctx.lineWidth=2;ctx.setLineDash([16,10]);}
    else{ctx.globalAlpha=0.55;ctx.strokeStyle='#c08aff';ctx.lineWidth=24+6*Math.sin(stateT*60);ctx.setLineDash([]);}
    ctx.beginPath();ctx.moveTo(m.x-ca*L,m.y-sa*L);ctx.lineTo(m.x+ca*L,m.y+sa*L);ctx.stroke();
    if(m.t<=0){ctx.globalAlpha=1;ctx.strokeStyle='#ffffff';ctx.lineWidth=6;ctx.stroke();}
    ctx.setLineDash([]);ctx.globalAlpha=1;}
  ctx.restore();
}

/* ---------- FUSION: overcrowded aliens merge into an Amalgam ---------- */
var fusions=[],fusionCount=0,fusionCd=0,fusionChk=0,toast={t:0,text:'',sub:'',col:'#fff'};
var AB_OF={crawler:'leap',runner:'leap',mite:'leap',spitter:'acid',brute:'charge',exploder:'nova',flyer:'blink',tunneler:'blink',phantom:'cloak',mender:'regen',bulwark:'armor',splitter:'split'};
var AB_NAME={leap:'POUNCE',acid:'ACID SPRAY',charge:'CHARGE',nova:'SPIKE NOVA',blink:'BLINK',regen:'REGEN',armor:'ARMOR',split:'SPLIT',cloak:'CLOAK'};
function showToast(text,sub,col){toast={t:3.2,max:3.2,text:text,sub:sub||'',col:col||'#ffd76a'};}
function fusionLimit(){
  if(story)return story.phase==='room'&&!CHAP[story.room].boss?2:0;
  if(wave<=5||queenRef||bossWarn)return 0;
  return wave>=12?3:2;
}
function fusionCand(e){return !e.dead&&!e.fusing&&!e.hidden&&!(e.dying>0)&&!isBoss(e)&&e.type!=='node'&&e.type!=='amalgam';}
function checkFusion(){
  fusionChk-=DT;if(fusionCd>0)fusionCd-=DT;
  if(fusionChk>0)return;fusionChk=0.5;
  if(fusions.length||fusionCd>0||fusionCount>=fusionLimit())return;
  var c=enemies.filter(fusionCand),crowd=story?Math.max(12,CHAP[story.room].cap-4):20;
  if(c.length<crowd)return;
  var best=null,bn=0,i,j;
  for(i=0;i<Math.min(c.length,60);i++){var n=0;for(j=0;j<c.length;j++){var dx=c[j].x-c[i].x,dy=c[j].y-c[i].y;if(dx*dx+dy*dy<230*230)n++;}if(n>bn){bn=n;best=c[i];}}
  if(!best||bn<7)return;
  var mem=c.filter(function(o){var dx=o.x-best.x,dy=o.y-best.y;return dx*dx+dy*dy<230*230;});
  mem.sort(function(a,b){return Math.hypot(a.x-best.x,a.y-best.y)-Math.hypot(b.x-best.x,b.y-best.y);});
  startFusion(mem.slice(0,Math.min(mem.length,randi(7,10))));
}
function startFusion(m){
  var x=0,y=0;m.forEach(function(e){x+=e.x;y+=e.y;});x/=m.length;y/=m.length;
  var f={x:x,y:y,t:2.6,max:2.6,m:m,n0:m.length};m.forEach(function(e){e.fusing=f;});
  fusions.push(f);fusionCount++;fusionCd=16;
  banner.text='FUSION DETECTED';banner.sub='THE SWARM IS MERGING  -  KILL THEM BEFORE IT FINISHES';banner.t=2.6;
  sfx('siren');sfx('growl');shake(5);
  if(story)say('They are merging into something bigger! Kill them before it finishes!',3.5);
}
function amalgamAbil(types){
  var cnt={},k;types.forEach(function(t){var a=AB_OF[t];if(a)cnt[a]=(cnt[a]||0)+1;});
  var list=Object.keys(cnt).sort(function(a,b){return cnt[b]-cnt[a];}).slice(0,3);
  if(list.length<2)list.push(list[0]==='charge'?'leap':'charge');
  return list;
}
function finishFusion(f,live){
  var hp=0,types=[],cols=[];
  live.forEach(function(e){hp+=e.hp;types.push(e.type);cols.push(ET[e.type].col2||ET[e.type].col);e.dead=true;});
  var a=spawnEnemy('amalgam',f.x,f.y);netSend({t:'fuse'});
  a.hp=a.maxHp=clamp(hp*1.15,380,3200);a.abil=amalgamAbil(types);a.cols=cols.slice(0,6);a.n=live.length;a.abT=1.5;a.abI=0;
  rings.push({x:f.x,y:f.y,r:200,life:0.4,max:0.4,col:'#ffffff'});rings.push({x:f.x,y:f.y,r:380,life:0.7,max:0.7,col:'#ff3a6a'});
  burst(f.x,f.y,70,BLOODS.concat(['#ffffff','#c08aff']),560,0.9,7);splat(f.x,f.y,2.6,0,0);scorch(f.x,f.y,60);
  shake(14);sfx('roar');sfx('bossboom');flashT=0.2;
  showToast('AMALGAM  -  '+live.length+' ALIENS FUSED',a.abil.map(function(k){return AB_NAME[k];}).join('  /  '),'#ff6a8a');
}
function updateFusions(){
  checkFusion();
  for(var i=fusions.length-1;i>=0;i--){var f=fusions[i];f.t-=DT;
    var live=f.m.filter(function(e){return !e.dead;});
    if(live.length){var x=0,y=0;live.forEach(function(e){x+=e.x;y+=e.y;});f.x+=(x/live.length-f.x)*0.1;f.y+=(y/live.length-f.y)*0.1;}
    if(Math.random()<0.7){var pa=rand(0,TAU),pd=rand(30,90);part(f.x+Math.cos(pa)*pd,f.y+Math.sin(pa)*pd,-Math.cos(pa)*pd*2,-Math.sin(pa)*pd*2,0.4,pick(BLOODS.concat(['#ff3a6a'])),4,0.96);}
    if(live.length<4){fusions.splice(i,1);live.forEach(function(e){e.fusing=null;});
      banner.text='FUSION DISRUPTED';banner.sub='+75 CREDITS';banner.t=2;credits+=75;earned+=75;sfx('clear');
      if(story)say('You broke it up! Nice work.',2.5);continue;}
    if(f.t<=0){fusions.splice(i,1);finishFusion(f,live);}
  }
  if(toast.t>0)toast.t-=DT;
}
function updateFuser(e){
  var f=e.fusing,dx=f.x-e.x,dy=f.y-e.y,d=Math.hypot(dx,dy)||1,k=1-f.t/f.max;
  var sp=(120+k*260)*DT;if(d>12){e.x+=dx/d*Math.min(d-10,sp);e.y+=dy/d*Math.min(d-10,sp);}
  e.a=Math.atan2(dy,dx)+Math.sin(stateT*20+e.ph)*0.4;e.ph+=DT*14;e.flash=Math.random()<k*0.3?0.05:e.flash;
}
function drawFusions(){
  for(var i=0;i<fusions.length;i++){var f=fusions[i],k=1-f.t/f.max;
    ctx.save();ctx.globalCompositeOperation='lighter';ctx.globalAlpha=0.35+k*0.4;ctx.drawImage(SPR_R,f.x-160,f.y-160,320,320);ctx.restore();
    ctx.lineCap='round';
    f.m.forEach(function(e,j){if(e.dead)return;var mx=(e.x+f.x)/2+Math.sin(stateT*6+j)*30,my=(e.y+f.y)/2+Math.cos(stateT*5+j)*30;
      ctx.strokeStyle='rgba(120,20,40,0.85)';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.quadraticCurveTo(mx,my,f.x,f.y);ctx.stroke();
      ctx.strokeStyle='rgba(255,90,140,'+(0.4+0.5*Math.sin(stateT*12+j))+')';ctx.lineWidth=2.5;ctx.stroke();});
    var r=10+k*26+Math.sin(stateT*16)*3;
    ctx.fillStyle='#3a0a1c';ctx.beginPath();ctx.arc(f.x,f.y,r+4,0,TAU);ctx.fill();
    ctx.fillStyle='#8a1a3a';ctx.beginPath();ctx.arc(f.x,f.y,r,0,TAU);ctx.fill();
    for(var q=0;q<5;q++){ctx.fillStyle='#c83a6a';ctx.beginPath();ctx.arc(f.x+Math.cos(q*1.3+stateT*3)*r*0.5,f.y+Math.sin(q*1.7+stateT*2)*r*0.5,r*0.25,0,TAU);ctx.fill();}
    for(q=0;q<3;q++){var rr=((stateT*1.6+q/3)%1);ctx.strokeStyle='rgba(255,60,110,'+(1-rr)+')';ctx.lineWidth=3;ctx.beginPath();ctx.arc(f.x,f.y,40+rr*170*(1-k*0.5),0,TAU);ctx.stroke();}
    ctx.fillStyle='rgba(0,0,0,0.6)';ctx.fillRect(f.x-60,f.y-r-40,120,10);ctx.fillStyle='#ff3a6a';ctx.fillRect(f.x-60,f.y-r-40,120*k,10);
    txt('FUSING '+Math.floor(k*100)+'%',f.x,f.y-r-52,12,'#ffb0c0','center');
  }
}
function drawFusionHUD(){
  if(fusions.length){
    var f=fusions[0],k=1-f.t/f.max,p=0.5+0.5*Math.sin(stateT*12);
    var g=ctx.createRadialGradient(LW/2,LH/2,LH*0.35,LW/2,LH/2,Math.max(LW,LH)*0.7);g.addColorStop(0,'rgba(255,0,40,0)');g.addColorStop(1,'rgba(255,0,40,'+(0.15+p*0.15)+')');
    ctx.fillStyle=g;ctx.fillRect(0,0,LW,LH);
    ctx.fillStyle='rgba(40,0,10,0.75)';ctx.fillRect(LW/2-200,102,400,40);ctx.strokeStyle='#ff3a6a';ctx.lineWidth=1.5;ctx.strokeRect(LW/2-199.5,102.5,399,39);
    txt('!  FUSION IN PROGRESS  -  KILL THEM  !',LW/2,116,13,p>0.5?'#ffffff':'#ff8aa0','center');
    ctx.fillStyle='#2a0810';ctx.fillRect(LW/2-180,128,360,6);ctx.fillStyle='#ff3a6a';ctx.fillRect(LW/2-180,128,360*k,6);
    var sx=f.x-cam.x,sy=f.y-cam.y;
    if(sx<30||sx>LW-30||sy<30||sy>LH-30){var a=Math.atan2(sy-LH/2,sx-LW/2),R0=Math.min(LW,LH)*0.4,ax=LW/2+Math.cos(a)*R0,ay=LH/2+Math.sin(a)*R0;
      ctx.save();ctx.translate(ax,ay);ctx.rotate(a);ctx.fillStyle='#ff3a6a';ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(-8,-12);ctx.lineTo(-3,0);ctx.lineTo(-8,12);ctx.closePath();ctx.fill();ctx.restore();txt('FUSION',ax,ay+22,10,'#ff8aa0','center');}
  }
  if(toast.t>0){var a2=clamp(toast.t/0.4,0,1)*clamp((toast.max-toast.t)/0.25,0,1);ctx.globalAlpha=a2;
    ctx.fillStyle='rgba(0,0,0,0.7)';ctx.fillRect(LW/2-260,150,520,54);ctx.strokeStyle=toast.col;ctx.lineWidth=1.5;ctx.strokeRect(LW/2-259.5,150.5,519,53);
    txt(toast.text,LW/2,168,16,toast.col,'center');txt(toast.sub,LW/2,190,11,'#eafff8','center');ctx.globalAlpha=1;}
}
/* amalgam AI: inherits 2-3 abilities from what it absorbed */
function amalgamAI(e,dist,toP,dx,dy){
  var sp=e.sp,j;
  if(e.cloakT>0){e.cloakT-=DT;}
  if(e.mode==='pounce'){e.mt-=DT;sp=640;e.oang=e.ca;if(e.mt<=0)e.mode='chase';return sp;}
  if(e.mode==='wind'){e.mt-=DT;sp=0;e.oang=e.ca;if(e.mt<=0){e.mode='charge';e.mt=0.6;sfx('growl');}return sp;}
  if(e.mode==='charge'){e.mt-=DT;sp=600;e.oang=e.ca;e.a=e.ca;if(e.mt<=0)e.mode='chase';return sp;}
  e.abT-=DT;
  if(e.abT<=0&&dist<700){
    var ab=e.abil[e.abI%e.abil.length];e.abI++;e.abT=rand(2.2,3.2);
    if(ab==='leap'||ab==='armor'||ab==='split'){if(e.abil.indexOf('leap')>=0||ab==='leap'){e.mode='pounce';e.mt=0.32;e.ca=lead(e,640);sfx('screech');}else{e.mode='wind';e.mt=0.45;e.ca=lead(e,600);}}
    else if(ab==='acid'){var la=lead(e,420);for(j=-2;j<=2;j++)spit(e.x,e.y,la+j*0.16,420,13);sfx('spit');}
    else if(ab==='charge'){e.mode='wind';e.mt=0.45;e.ca=lead(e,600);floatTxt(e.x,e.y-e.r-14,'!','#ff4a4a');}
    else if(ab==='nova'){for(j=0;j<14;j++)spit(e.x,e.y,j*TAU/14+stateT,330,12);rings.push({x:e.x,y:e.y,r:120,life:0.3,max:0.3,col:'#ff8a2a'});sfx('boom');shake(4);}
    else if(ab==='blink'){burst(e.x,e.y,18,['#c08aff','#ffffff'],300,0.4,4);var ba=player.a+Math.PI+rand(-1,1),nx=clamp(player.x+Math.cos(ba)*150,T+30,WW-T-30),ny=clamp(player.y+Math.sin(ba)*150,T+30,WH-T-30);
      if(!solid[Math.floor(ny/T)*MW+Math.floor(nx/T)]){e.x=nx;e.y=ny;}burst(e.x,e.y,18,['#c08aff','#ffffff'],300,0.4,4);sfx('dash');}
    else if(ab==='regen'){e.hp=Math.min(e.maxHp,e.hp+e.maxHp*0.12);rings.push({x:e.x,y:e.y,r:90,life:0.4,max:0.4,col:'#7dffb0'});floatTxt(e.x,e.y-e.r-14,'+REGEN','#7dffb0');sfx('heal');}
    else if(ab==='cloak'){e.cloakT=2.2;burst(e.x,e.y,14,['#ffffff','#9fb8c4'],200,0.3,3);}
  }
  return sp;
}
function drawAmalgam(e,r,d,C,ph,open,fl){
  var sw=Math.sin(ph*0.8),cols=e.cols||['#6a3a5a'],s,i;
  ctx.lineCap='round';ctx.lineJoin='round';
  // arms: shoulder -> elbow -> clawed hand, swinging like a walking predator
  for(s=-1;s<=1;s+=2){
    var swing=sw*s*0.35,shx=-r*0.05,shy=s*r*0.82,elx=r*(0.25+swing*0.5),ely=s*r*1.22,hx=r*(0.95+swing),hy=s*r*(0.78-swing*0.3);
    ctx.strokeStyle=C('#1e1020');ctx.lineWidth=r*0.34;ctx.beginPath();ctx.moveTo(shx,shy);ctx.lineTo(elx,ely);ctx.lineTo(hx,hy);ctx.stroke();
    ctx.strokeStyle=C(cols[(s+1)/2%cols.length]);ctx.lineWidth=r*0.2;ctx.stroke();
    ctx.fillStyle=C('#2a1626');ctx.beginPath();ctx.arc(hx,hy,r*0.17,0,TAU);ctx.fill();
    ctx.strokeStyle=C('#f4e6d8');ctx.lineWidth=r*0.07;for(i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(hx,hy);ctx.quadraticCurveTo(hx+r*0.25,hy+i*r*0.14,hx+r*0.42,hy+i*r*0.2-s*r*0.04);ctx.stroke();}
    ctx.fillStyle=C('#f4e6d8');ctx.beginPath();ctx.moveTo(elx-r*0.08,ely);ctx.lineTo(elx-r*0.35,ely+s*r*0.22);ctx.lineTo(elx+r*0.06,ely+s*r*0.05);ctx.fill();
  }
  // broad shoulders / back
  ctx.fillStyle=C('#1e1020');ctx.beginPath();ctx.moveTo(-r*0.35,-r);ctx.quadraticCurveTo(r*0.35,-r*1.02,r*0.3,0);ctx.quadraticCurveTo(r*0.35,r*1.02,-r*0.35,r);ctx.quadraticCurveTo(-r*0.6,0,-r*0.35,-r);ctx.fill();
  ctx.fillStyle=C('#3a1e34');ctx.beginPath();ctx.moveTo(-r*0.3,-r*0.88);ctx.quadraticCurveTo(r*0.25,-r*0.9,r*0.22,0);ctx.quadraticCurveTo(r*0.25,r*0.9,-r*0.3,r*0.88);ctx.quadraticCurveTo(-r*0.5,0,-r*0.3,-r*0.88);ctx.fill();
  // fused remains of the absorbed aliens on its back, each with a small eye
  for(i=0;i<Math.min(cols.length,6);i++){var py=(-0.62+i*0.25)*r,px=-r*(0.12+((i*37)%3)*0.07);
    ctx.fillStyle=C(cols[i]);ell(px,py,r*0.17,r*0.13);
    if(!fl){ctx.fillStyle=Math.sin(stateT*3+i*2)>-0.6?'#ffcf4a':'#3a1e34';ctx.beginPath();ctx.arc(px+r*0.04,py,r*0.045,0,TAU);ctx.fill();}}
  // spine ridge
  ctx.fillStyle=C('#f0d8e0');for(i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(-r*0.38,i*r*0.3-r*0.06);ctx.lineTo(-r*0.68,i*r*0.32);ctx.lineTo(-r*0.38,i*r*0.3+r*0.06);ctx.fill();}
  // shoulder spikes
  for(s=-1;s<=1;s+=2){ctx.beginPath();ctx.moveTo(-r*0.1,s*r*0.86);ctx.lineTo(-r*0.45,s*r*1.25);ctx.lineTo(r*0.08,s*r*0.98);ctx.fill();}
  if(!fl){ctx.strokeStyle='rgba(255,60,110,'+(0.45+0.3*Math.sin(stateT*6))+')';ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(r*0.15,-r*0.7);ctx.lineTo(-r*0.05,-r*0.2);ctx.lineTo(r*0.12,r*0.25);ctx.lineTo(-r*0.02,r*0.72);ctx.stroke();}
  // head
  ctx.fillStyle=C('#2a1424');ell(r*0.38,0,r*0.36,r*0.3);
  ctx.fillStyle=C('#4a2440');ell(r*0.32,0,r*0.24,r*0.2);
  jaws(r*0.68,r*0.72,0.4,0.55,open,C('#f4e6d8'),r*0.1);
}

/* ---------- fx helpers ---------- */
function shake(a){if(opt.shake)shakeMag=Math.min(18,shakeMag+a);}
function part(x,y,vx,vy,life,col,size,fr){
  if(parts.length>700)parts.shift();
  parts.push({x:x,y:y,vx:vx,vy:vy,life:life,max:life,col:col,size:size,fr:fr||0.9});
}
function burst(x,y,n,cols,spd,life,size,dx,dy){
  for(var i=0;i<n;i++){
    var a=rand(0,TAU),s=rand(spd*0.2,spd);
    part(x,y,Math.cos(a)*s+(dx||0)*spd*0.6,Math.sin(a)*s+(dy||0)*spd*0.6,rand(life*0.5,life),typeof cols==='string'?cols:pick(cols),rand(size*0.5,size));
  }
}
function floatTxt(x,y,s,col){floats.push({x:x,y:y,s:s,col:col,life:0.9});}
function drop(x,y,type,val){
  var a=rand(0,TAU),d=rand(0,14);
  pickups.push({type:type,x:clamp(x+Math.cos(a)*d,T+12,WW-T-12),y:clamp(y+Math.sin(a)*d,T+12,WH-T-12),val:val||0,life:type==='sh'||type==='mg'?90:26,ph:rand(0,TAU)});
}
function breakCrate(c){
  if(!c||c.dead)return;
  c.dead=true;var idx=c.ty*MW+c.tx;solid[idx]=0;crateAt[idx]=null;flowT=0;
  var cx=c.x+c.w/2,cy=c.y+c.h/2;
  if(c.barrel){explode(cx,cy,135,160,25);return;}
  burst(cx,cy,16,['#aab4bc','#6a7680','#e8892a','#dfe6ea'],260,0.6,6);
  scorch(cx,cy,20);sfx('crate');shake(3);
  if(c.shield){drop(cx,cy,'sh');return;}
  if(Math.random()<0.09){drop(cx,cy,'mg');return;}
  var r=Math.random();
  if(r<0.45){drop(cx,cy,'cr',randi(10,25));if(Math.random()<0.4)drop(cx,cy,'cr',randi(5,15));}
  else if(r<0.75)drop(cx,cy,'am');
  else drop(cx,cy,'hp');
}
function explode(x,y,R,dmg,pdmg,acidic){
  var i;
  rings.push({x:x,y:y,r:R,life:0.35,max:0.35,col:acidic?'#b8ff3a':'#ffb040'});
  burst(x,y,24,acidic?['#c8ff3a','#7af03c','#fff']:['#ffd76a','#ff8a2a','#fff','#ff5a2a'],R*3.4,0.5,6);
  burst(x,y,10,['#39424a','#232a30'],R*1.6,0.9,9);
  if(acidic)splat(x,y,2.2,0,0);else scorch(x,y,R*0.5);
  shake(acidic?6:11);sfx('boom');
  for(i=0;i<enemies.length;i++){
    var e=enemies[i];if(e.dead)continue;
    var dx=e.x-x,dy=e.y-y,d=Math.hypot(dx,dy)||1;
    if(d<R+e.r)hitEnemy(e,dmg*(1-0.6*d/(R+e.r)),dx/d,dy/d,420,true);
  }
  for(i=0;i<crates.length;i++){
    var c=crates[i];if(c.dead)continue;
    if(Math.hypot(c.x+c.w/2-x,c.y+c.h/2-y)<R+10){if(c.barrel){if(c.fuse<=0)c.fuse=0.14;}else breakCrate(c);}
  }
  if(pdmg&&Math.hypot(player.x-x,player.y-y)<R*0.75)hurt(pdmg);
  if(bot&&Math.hypot(bot.x-x,bot.y-y)<R*0.75)botHurt(pdmg);
}
function hurt(d){
  if(player.inv>0||state!=='play'||test.god)return;
  d*=DIFFS[diff].dmg;if(armor)d*=0.7;
  if(shieldT>0){
    shieldHp-=d;player.inv=0.25;shake(3);sfx('shield');
    burst(player.x,player.y,8,['#9af6ff','#ffffff'],220,0.3,4);
    if(shieldHp<=0){shieldT=0;sfx('shielddown');floatTxt(player.x,player.y-30,'SHIELD BROKEN','#ff6a5a');rings.push({x:player.x,y:player.y,r:70,life:0.3,max:0.3,col:'#9af6ff'});}
    return;
  }
  player.hp-=d;player.inv=0.4;hurtT=0.35;shake(7);sfx('hurt');
  burst(player.x,player.y,8,'#ff4a4a',180,0.4,4);
  if(player.hp<=0&&((perkOn('secondwind')&&!secondUsed)||lives>0)){if(perkOn('secondwind')&&!secondUsed)secondUsed=true;else lives--;player.hp=player.maxHp*0.5;player.inv=2.2;
    rings.push({x:player.x,y:player.y,r:220,life:0.6,max:0.6,col:'#ff8a2a'});burst(player.x,player.y,50,['#ff8a2a','#ffd76a','#ffffff'],420,0.8,6);
    banner.text='SECOND WIND';banner.sub='YOU REFUSE TO DIE';banner.t=2;sfx('evolve');slowT=0.6;
    for(var sw=0;sw<enemies.length;sw++){var se=enemies[sw];if(se.dead||isBoss(se))continue;var sd2=Math.hypot(se.x-player.x,se.y-player.y)||1;if(sd2<220){se.kx+=(se.x-player.x)/sd2*900;se.ky+=(se.y-player.y)/sd2*900;}}
    return;}
  if(player.hp<=0){player.hp=0;state='over';stateT=0;mouse.down=false;sfx('over');saveBest();
    burst(player.x,player.y,40,['#ff4a4a','#ff9a3a','#ffffff'],380,0.9,6);shake(16);}
}
function hitEnemy(e,dmg,dx,dy,knock,ap){
  if(e.dead||e.hidden||e.dying>0)return;
  if(e.mode==='evolve'){if(Math.random()<0.3)burst(e.x-dx*e.r,e.y-dy*e.r,2,['#ffffff',BOSS2[e.type].col],200,0.25,3);return;}
  if(e.shield){burst(e.x-dx*e.r,e.y-dy*e.r,3,['#9af6ff','#ffffff'],200,0.25,3);sfx('shield');return;}
  if(e.type==='amalgam'&&e.abil&&e.abil.indexOf('armor')>=0&&!ap&&(-dx*Math.cos(e.a)-dy*Math.sin(e.a))>0.3){dmg*=0.4;if(Math.random()<0.3)burst(e.x+Math.cos(e.a)*e.r,e.y+Math.sin(e.a)*e.r,2,['#ffd76a'],200,0.2,2.5);}
  if(e.type==='bulwark'&&!ap&&(-dx*Math.cos(e.a)-dy*Math.sin(e.a))>0.3){
    e.blockT=0.12;burst(e.x+Math.cos(e.a)*e.r,e.y+Math.sin(e.a)*e.r,3,['#ffd76a','#ffffff'],220,0.2,2.5);sfx('shield');return;
  }
  if(e.type==='phantom')e.reveal=1.3;
  if(e.markT>0)dmg*=1.5;   // sniper mark scope
  e.hp-=dmg;e.flash=0.07;
  var m=13/e.r;if(e.type==='queen')m=e.stage===2?0.02:0.04;else if(e.type==='zero'||e.type==='node')m=0;
  e.kx+=dx*knock*m;e.ky+=dy*knock*m;
  burst(e.x,e.y,3,BLOODS,170,0.35,3.5,dx,dy);
  if(Math.random()<0.5)splat(e.x,e.y,0.5,dx,dy);
  sfx('hit');
  if(e.hp<=0)killEnemy(e,dx,dy);
}
function killEnemy(e,dx,dy){
  if(!e.dead&&!(isBoss(e)&&!e.final))codexOnKill(e);
  if(e.dead)return;
  if(isBoss(e)&&!e.final){if(e.stage===1){if(e.mode!=='evolve')startEvolve(e);return;}if(!(e.dying>0))startBossDeath(e);return;}
  e.dead=true;kills++;
  comboN++;comboT=2.6;
  var CALLS={10:'KILLING SPREE',20:'RAMPAGE',35:'UNSTOPPABLE',50:'EXTERMINATOR',75:'GODLIKE',100:'HIVE BREAKER'};
  if(CALLS[comboN]){call.t=1.8;call.text=CALLS[comboN];sfx('streak');}
  var d=ET[e.type],big=e.r/13,mult=comboMult();
  score+=Math.round(d.cr*10*mult*DIFFS[diff].sc);
  burst(e.x,e.y,Math.floor(10+big*8),BLOODS,280+big*40,0.6,4+big,dx,dy);
  burst(e.x,e.y,4,d.col2,200,0.5,4,dx,dy);
  splat(e.x,e.y,1+big*0.9,dx,dy);
  shake(1.2+big);sfx('die_'+e.type);
  var r=Math.random(),sca=0;
  if(r<0.72-sca)drop(e.x,e.y,'cr',Math.round(d.cr*rand(0.7,1.4)*mult));
  else if(r<0.8+sca)drop(e.x,e.y,'am');
  else if(r<0.845+sca*2)drop(e.x,e.y,'hp');
  if(perkOn('vampiric')&&player.hp>0&&player.hp<player.maxHp){var vh=comboN>=10?2:1;player.hp=Math.min(player.maxHp,player.hp+vh);if(Math.random()<0.3)floatTxt(player.x+rand(-10,10),player.y-24,'+'+vh,'#7af05a');}
  if(perkOn('acidblood')&&!isBoss(e)&&e.type!=='mite'&&Math.random()<0.6)acidPops.push({x:e.x,y:e.y,t:0.08});
  if(e.type==='brute'&&Math.random()<0.5)drop(e.x,e.y,'cr',randi(10,20));
  if(e.type==='husk'&&Math.random()<0.4){for(var hl=0;hl<2;hl++)spawnEnemy('mite',e.x+rand(-14,14),e.y+rand(-14,14));floatTxt(e.x,e.y-20,'LARVAE!','#c8ff3a');}
  if(e.type==='amalgam'&&e.abil&&e.abil.indexOf('split')>=0){for(var sm=0;sm<4;sm++)spawnEnemy('mite',e.x+rand(-20,20),e.y+rand(-20,20));}
  if(e.type==='splitter'&&!(queenRef&&(queenRef.dying>0||queenRef.mode==='evolve')))for(var sm2=0;sm2<3;sm2++)spawnEnemy('mite',e.x+rand(-14,14),e.y+rand(-14,14));
  if(e.type==='exploder')booms.push({t:0.07,x:e.x,y:e.y,R:85,dmg:45,pdmg:20,acidic:true});
  if(e.type==='queen'&&!queenSlain){queenSlain=true;floatTxt(player.x,player.y-40,'HEAVY SNIPER NOW IN THE ARMORY','#ff4a6a');}
  if(isBoss(e)){
    var zb=e.type==='zero',bonus=zb?15000:5000,i;
    queenRef=null;shake(18);sfx('bossboom');sfx('fanfare');flashT=0.8;slowT=0.9;
    rings.push({x:e.x,y:e.y,r:280,life:0.5,max:0.5,col:'#ffffff'});
    rings.push({x:e.x,y:e.y,r:460,life:0.75,max:0.75,col:zb?'#9af6ff':'#ff3a6a'});
    rings.push({x:e.x,y:e.y,r:680,life:1,max:1,col:'#ffd76a'});
    for(i=0;i<16;i++)drop(e.x+rand(-140,140),e.y+rand(-140,140),'cr',randi(20,40));
    drop(e.x+rand(-60,60),e.y+rand(-60,60),'hp');drop(e.x+rand(-60,60),e.y+rand(-60,60),'hp');drop(e.x+rand(-60,60),e.y+rand(-60,60),'am');drop(e.x+rand(-60,60),e.y+rand(-60,60),'am');
    splat(e.x,e.y,7,0,0);scorch(e.x,e.y,90);
    burst(e.x,e.y,150,BLOODS.concat(['#ffffff','#ffd76a']),640,1.3,9);
    score+=bonus;
    ach.t=6;ach.title=zb?'APEX PREDATOR':'QUEENSLAYER';ach.sub=(zb?'SPECIMEN ZERO DESTROYED':'HIVE QUEEN SLAIN')+'   +'+bonus+' SCORE';
    ach.sub2=!zb&&!story&&wave===10&&!owned[5]?'HEAVY SNIPER NOW FOR SALE IN THE ARMORY (600 CR)':'';
  }
}

/* ---------- player actions ---------- */
function magSize(i){var m=i===0&&dual?WEAP[0].mag*2:WEAP[i].mag;if(att(i,'pmag')||att(i,'drum')||att(i,'rmag'))m=Math.round(m*1.5);return m;}
function hasAmmo(i){return mag[i]>0||ammo[i]>0;}
function startReload(){
  var i=player.w;
  if(reloadT>0||mag[i]>=magSize(i)||ammo[i]<=0)return;
  reloadT=WEAP[i].rl*(i===0&&dual?1.4:1)*(perkOn('reload')?0.65:1)*(i===4&&att(4,'quick')?0.6:1);reloadMax=reloadT;sfx('reload');
}
function setWeapon(i){
  if(i===player.w||state!=='play')return;
  if(!owned[i]){sfx('empty');floatTxt(player.x,player.y-26,i===5&&!queenSlain?'LOCKED - KILL THE HIVE QUEEN FIRST':'LOCKED - BUY IN ARMORY','#ff6a5a');return;}
  if(!hasAmmo(i)){sfx('empty');floatTxt(player.x,player.y-26,'NO AMMO','#ff6a5a');return;}
  player.w=i;player.cd=Math.max(player.cd,0.12);reloadT=0;sfx('switch');
  if(mag[i]<=0)startReload();
}
function toggleDual(){
  dual=!dual;sfx('dual');reloadT=0;
  if(!dual)mag[0]=Math.min(mag[0],WEAP[0].mag);
  if(player.w!==0){player.w=0;player.cd=Math.max(player.cd,0.12);}
  floatTxt(player.x,player.y-26,dual?'DUAL PISTOLS':'SINGLE PISTOL','#2ff5c0');
}
function beamLen(x,y,a,max){
  var ca=Math.cos(a),sa=Math.sin(a),d;
  for(d=0;d<max;d+=12){
    var tx=Math.floor((x+ca*d)/T),ty=Math.floor((y+sa*d)/T);
    if(tx<0||ty<0||tx>=MW||ty>=MH||solid[ty*MW+tx]===1)break;
  }
  return d;
}
function fireSniper(mx,my,dmg,range){
  var ca=Math.cos(player.a),sa=Math.sin(player.a),d,i;
  for(d=0;d<range;d+=8){
    var x=mx+ca*d,y=my+sa*d,tx=Math.floor(x/T),ty=Math.floor(y/T);
    if(tx<0||ty<0||tx>=MW||ty>=MH)break;
    var sd=solid[ty*MW+tx];
    if(sd===1)break;
    if(sd===2){var c=crateAt[ty*MW+tx];if(c&&x>=c.x&&x<=c.x+c.w&&y>=c.y&&y<=c.y+c.h)breakCrate(c);}
  }
  var ex=mx+ca*d,ey=my+sa*d;
  beams.push({x1:mx,y1:my,x2:ex,y2:ey,life:0.25,max:0.25});
  burst(ex,ey,10,['#ff4a6a','#ffffff','#ffd0d8'],300,0.3,4);
  var list=[],FALL=[1,0.6,0.35];
  for(i=0;i<enemies.length;i++){
    var e=enemies[i];if(e.dead||e.hidden)continue;
    var px=e.x-mx,py=e.y-my,t=clamp(px*ca+py*sa,0,d),qx=px-ca*t,qy=py-sa*t,rr=e.r+9;
    if(qx*qx+qy*qy<rr*rr)list.push([t,e]);
  }
  list.sort(function(a,b){return a[0]-b[0];});
  var rail=att(5,'rail'),maxP=rail?99:wmk[5]>=2?5:3;FALL=[1,0.6,0.35,0.25,0.2];
  for(i=0;i<Math.min(maxP,list.length);i++){var te=list[i][1];hitEnemy(te,dmg*(rail?1:FALL[i]),ca,sa,240,true);
    if(att(5,'mark')&&!te.dead)te.markT=6;
    if(wmk[5]>=3&&te.dead)miniBlast(te.x,te.y,90,dmg*0.5,'#ff4a6a');}
  if(list.length>maxP){beams[beams.length-1].x2=mx+ca*list[maxP-1][0];beams[beams.length-1].y2=my+sa*list[maxP-1][0];}
  if(att(5,'tip'))miniBlast(beams[beams.length-1].x2,beams[beams.length-1].y2,80,dmg*0.6,'#ff8a2a');
}
function dashTick(){
  if(perkOn('blazing')&&(!fires.length||Math.hypot(fires[fires.length-1].x-player.x,fires[fires.length-1].y-player.y)>26))fires.push({x:player.x,y:player.y,t:3,max:3});
  if(up.dash<=0)return;
  for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.dead||e.hidden||e.dying>0||player.dashHit.indexOf(e)>=0)continue;
    var d=Math.hypot(e.x-player.x,e.y-player.y);
    if(d<e.r+player.r+10){player.dashHit.push(e);var dd=dashDmg()*(isBoss(e)?0.6:1);
      hitEnemy(e,dd,player.dx,player.dy,isBoss(e)?0:520,true);floatTxt(e.x,e.y-e.r-8,String(Math.round(dd)),'#2ff5c0');
      rings.push({x:e.x,y:e.y,r:e.r+26,life:0.2,max:0.2,col:'#2ff5c0'});burst(e.x,e.y,8,['#2ff5c0','#ffffff'],300,0.3,4,player.dx,player.dy);shake(3);sfx('hit');}}
}
function chainZap(x,y,dmg){
  var hit=[],cx=x,cy=y;
  for(var k=0;k<3;k++){
    var best=null,bd=k?260:440;
    for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.dead||e.hidden||e.dying>0||hit.indexOf(e)>=0)continue;var d=Math.hypot(e.x-cx,e.y-cy);if(d<bd){bd=d;best=e;}}
    if(!best)break;
    bolts.push({x1:cx,y1:cy,x2:best.x,y2:best.y,life:0.22,max:0.22,seed:Math.random()*99});
    hit.push(best);hitEnemy(best,dmg,0,0,0,true);burst(best.x,best.y,5,['#9ad8ff','#ffffff'],200,0.25,3);cx=best.x;cy=best.y;
  }
  if(hit.length)sfx('zbeam');
}
function doDash(){
  if(player.dashCd>0||player.dash>0)return;
  var mx=0,my=0;
  if(keys.KeyW||keys.ArrowUp)my-=1;if(keys.KeyS||keys.ArrowDown)my+=1;
  if(keys.KeyA||keys.ArrowLeft)mx-=1;if(keys.KeyD||keys.ArrowRight)mx+=1;
  if(touch.move){mx+=touch.mx;my+=touch.my;}
  if(!mx&&!my){mx=Math.cos(player.a);my=Math.sin(player.a);}
  var l=Math.hypot(mx,my);player.dx=mx/l;player.dy=my/l;
  if(perkOn('mirror')&&decoyCd<=0){decoys.push({x:player.x,y:player.y,a:player.a,t:2.5,max:2.5});decoyCd=3.5;}
  dashedT=0.35;player.dashHit=[];player.dash=dashDur();player.dashCd=dashCdT();player.inv=Math.max(player.inv,dashDur()+0.13);sfx('dash');
}
function fire(){
  var wi=player.w,w=WEAP[wi];
  if(mag[wi]<=0){
    if(ammo[wi]>0)startReload();
    else{player.w=0;player.cd=0.2;reloadT=0;sfx('empty');floatTxt(player.x,player.y-26,'OUT OF AMMO','#ff6a5a');}
    return;
  }
  var cd=w.cd,spread=w.spread,dmg=w.dmg*(1+0.2*wd[wi]),side=3;
  var crit=false,mk=wmk[wi],pel=w.pellets,knock=w.knock,pier=0,rng=w.range,nth=(player.nth=(player.nth||0)+1);
  dmg*=(wi===0?[1,1,1.25]:wi===3?[1,1.1,2]:[1,1.2,1.4])[mk-1];   // weapon stage
  if(wi===0&&att(0,'hair'))cd*=0.77;
  if(wi===1){if(att(1,'slug')){pel=1;dmg*=w.pellets*0.8;spread=0.02;pier=3;}else if(att(1,'choke')){pel=12;spread*=1.6;}if(att(1,'flech'))pier=Math.max(pier,1);}
  if(wi===2){if(att(2,'stab'))spread*=0.5;if(att(2,'shred'))knock*=3;}
  if(wi===3){if(att(3,'wide'))spread*=1.6;if(att(3,'pump'))dmg*=1.25;if(att(3,'cryo'))dmg*=0.7;}
  if(wi===5&&att(5,'bolt'))cd*=0.65;
  if(wi===6){if(mk>=2)cd*=0.87;if(att(6,'burst'))spread*=0.5;if(att(6,'tracer')){dmg*=1.1;rng+=150;}if(att(6,'ap'))pier=1;}
  if(wi===0&&dual){cd*=pistolLv===2?0.62:0.55;dmg*=0.7;spread=0.13;player.hand=-player.hand;side=player.hand*8;}
  else if(wi===0&&Math.random()<(att(0,'hollow')?0.35:0.2)){crit=true;dmg*=2;}
  var aimA=player.a;
  if(wi===6&&rsight.t&&!rsight.t.dead)aimA=Math.atan2(rsight.t.y-player.y,rsight.t.x-player.x);
  if(ocl){dmg*=1+0.25*ocl;cd/=1+0.15*ocl;}
  player.cd=cd/(1+0.12*wr[wi])/(perkOn('adrenaline')&&player.hp<player.maxHp*0.3?1.4:1);
  if(perkOn('chain')&&++shotN%5===0)chainZap(player.x,player.y,25*(1+0.2*wd[wi]));
  if(wi===6&&att(6,'burst')){player.burstN=(player.burstN||0)+1;player.cd=player.burstN%3===0?0.34:0.06;}
  if(wi===2&&att(2,'tesla')&&nth%10===0)chainZap(player.x,player.y,dmg*3);
  mag[wi]--;
  var ca=Math.cos(player.a),sa=Math.sin(player.a),mx=player.x+ca*16-sa*side,my=player.y+sa*16+ca*side;
  player.fside=side;
  if(w.type==='beam')fireSniper(mx,my,dmg,w.range);
  else for(var p=0;p<pel;p++){
    var a=aimA+(Math.random()-0.5)*spread,sp=w.speed*(pel>1?rand(0.85,1.1):1);
    var b={type:w.type||'shot',x:mx,y:my,px:mx,py:my,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:rng/sp,dmg:dmg,knock:knock,col:w.col};
    if(b.type==='flame'){b.life=rand(0.4,0.55)*(mk>=2?1.3:1);b.max=b.life;b.hits=[];if(mk>=3)b.col='#5ac8ff';if(att(3,'cryo')){b.cryo=true;b.col='#bff4ff';}if(att(3,'napalm'))b.napalm=true;}
    if(b.type==='nade'){b.R=w.radius*(att(4,'payload')?1.4:1);b.spin=0;b.cluster=att(4,'cluster')?4:mk>=3?3:0;b.sticky=att(4,'sticky');}
    if(b.type==='laser'){b.pierce=w.pierce;b.hits=[];}
    if(pier&&b.type==='shot'){b.pierce=pier;b.hits=[];}
    if(wi===1&&(att(1,'dragon')||mk>=3))b.burn=true;
    if(wi===2&&mk>=3&&Math.random()<0.25)b.burn=true;
    if(wi===0&&att(0,'rico'))b.rico=true;
    if(wi===0&&mk>=3&&nth%4===0){b.plasma=true;b.col='#c08aff';}
    if(wi===6&&mk>=3&&nth%10===0){b.boomer=true;b.col='#ffb040';}
    if(crit){b.crit=true;b.col='#ffffff';}
    bullets.push(b);
  }
  shake(w.shake);sfx(w.sfx);
  if(w.type!=='flame'){
    player.flash=0.055;
    if(w.type!=='laser')part(player.x,player.y,-sa*rand(90,160)-ca*40,ca*rand(90,160)-sa*40,0.5,'#d8b04a',2.6,0.88);
  }
  if(mag[wi]<=0){
    if(ammo[wi]>0)startReload();
    else if(wi!==0){floatTxt(player.x,player.y-26,'OUT OF AMMO','#ff6a5a');player.w=0;player.cd=0.2;}
  }
}
function upCost(l){return 45+l*18;}   // per DMG/RATE level; a weapon maxed to Mk III costs about 2,370 credits in all (about wave 10)
function updateSight(){
  rsight.on=state==='play'&&player.w===6&&owned[6];
  if(!rsight.on){rsight.t=null;return;}
  var a=player.a,ca=Math.cos(a),sa=Math.sin(a),mx=player.x+ca*18,my=player.y+sa*18,R=WEAP[6].range+(att(6,'tracer')?150:0),L=beamLen(mx,my,a,R),best=null,bt=L,i;
  for(i=0;i<enemies.length;i++){
    var e=enemies[i];if(e.dead||e.hidden||e.dying>0||(e.type==='phantom'&&e.vis<0.4))continue;
    var px=e.x-mx,py=e.y-my,t=px*ca+py*sa;if(t<0||t>L)continue;
    var q=Math.abs(px*sa-py*ca);
    if(q<e.r+16&&t<bt){bt=t;best=e;}
  }
  rsight.t=best;rsight.x2=mx+ca*(best?bt:L);rsight.y2=my+sa*(best?bt:L);rsight.x1=mx;rsight.y1=my;
}
var SHOP=[
  {name:'AMMO RESUPPLY',desc:'Tops up every weapon you own',cost:function(){return 60;},
    can:function(){for(var i=1;i<NW;i++)if(owned[i]&&ammo[i]<WEAP[i].max)return true;return false;},lvl:function(){return '';},
    buy:function(){for(var i=1;i<NW;i++)if(owned[i])ammo[i]=Math.min(WEAP[i].max,ammo[i]+WEAP[i].refill);}},
  {name:'MEDKIT',desc:'+50 health',cost:function(){return 50;},
    can:function(){return player.hp<player.maxHp;},lvl:function(){return '';},
    buy:function(){player.hp=Math.min(player.maxHp,player.hp+(skinOn('hazmat')?75:50));}},
  {name:'MAX HEALTH +25',desc:'Armor plating, also heals 25',cost:function(){return 120+up.max*40;},
    can:function(){return up.max<4;},lvl:function(){return up.max+'/4';},
    buy:function(){up.max++;player.maxHp+=25;player.hp=Math.min(player.maxHp,player.hp+25);}},
  {name:'AUTO-TURRET',desc:'Press T to drop it. Shoots aliens in short range (max 3)',cost:function(){return 250;},
    can:function(){return turretCount()<3;},lvl:function(){return turretCount()+'/3';},buy:function(){turInv++;}},
  {name:'SPRINT BOOSTERS',desc:'Hold SHIFT to sprint (3s stamina, recharges)',cost:function(){return 150;},
    can:function(){return !up.sprint;},lvl:function(){return up.sprint?'OWNED':' ';},
    buy:function(){up.sprint=true;}}
];
function dashDmg(l){return [0,22,34,48][l==null?up.dash:l];}
function dashSpd(){return 880*(1+0.12*(up.dspd||0));}
function dashDur(){return 0.17*(1+0.22*(up.drng||0))*(skinOn('void')?1.3:1);}
function dashCdT(){return 1.3*(1-0.15*(up.dspd||0));}
function dashInfo(kind){
  var l=kind==='dstr'?up.dash:kind==='dspd'?up.dspd:up.drng,cost=kind==='dstr'?180+l*120:150+l*100;
  return {ok:l<3,cost:cost,label:{dstr:'HIT ',dspd:'SPEED ',drng:'RANGE '}[kind]+l+'/3'};
}
function buyDash(kind){
  var inf=dashInfo(kind);
  if(!inf.ok){sfx('deny');shopSay('ALREADY MAXED');return;}
  if(credits<inf.cost){sfx('deny');shopSay('NOT ENOUGH CREDITS');return;}
  credits-=inf.cost;sfx('buy');
  if(kind==='dstr'){up.dash++;shopSay('DASH STRIKE: DASHING THROUGH ALIENS DEALS '+dashDmg()+' DAMAGE');}
  else if(kind==='dspd'){up.dspd++;shopSay('DASH SPEED UP: FASTER DASH, SHORTER RECHARGE ('+dashCdT().toFixed(2)+'s)');}
  else{up.drng++;shopSay('DASH RANGE UP: DASH GOES '+Math.round(dashSpd()*dashDur())+' UNITS');}
}
function shopSay(t){shopMsg.text=t;shopMsg.t=1.4;}
function buy(i){
  var it=SHOP[i];if(!it)return;
  if(!it.can()){sfx('deny');shopSay(it.lvl()?'ALREADY OWNED OR MAXED':'NOT NEEDED RIGHT NOW');return;}
  var c=it.cost();
  if(credits<c){sfx('deny');shopSay('NOT ENOUGH CREDITS');return;}
  credits-=c;it.buy();sfx('buy');shopSay('PURCHASED: '+it.name);
}
function wCap(wi){return 4+2*(Math.max(wmk?wmk[wi]:1,wi===0?pistolLv:1)-1);}   // 4 at Mk I, 6 at Mk II, 8 at Mk III
function wInfo(wi,kind){
  if(wi===-2)return dashInfo(kind);
  if(wi<0)return botInfo(kind);
  if(kind==='unlock'){
    if(wi===5&&!queenSlain)return {ok:false,cost:0,label:'KILL THE HIVE QUEEN TO STOCK IT',msg:'KILL THE HIVE QUEEN (WAVE 10) FIRST',tag:'LOCKED'};
    return {ok:true,cost:WEAP[wi].unlock,label:'UNLOCK'+(wi===5?' HEAVY SNIPER':wi===6?' RIFLE - LASER SIGHT':'')};
  }
  if(kind==='pevo')return {ok:true,cost:450,label:'EVOLVE TO LEVEL 2: LASER PISTOL'};
  var l=kind==='dmg'?wd[wi]:kind==='rate'?wr[wi]:kind==='range'?snR:kind==='lrange'?rifR:snA,cap=kind==='range'||kind==='ammo'||kind==='lrange'?4:wCap(wi);
  var cost=wi===5?Math.round(upCost(l)*(kind==='dmg'?1.3:kind==='ammo'?0.8:1)):upCost(l);
  return {ok:l<cap,cost:cost,label:{dmg:'DMG ',rate:'RATE ',range:'RANGE ',ammo:'AMMO ',lrange:'LASER '}[kind]+l+'/'+cap};
}
function buyW(wi,kind){
  if(wi===-2){buyDash(kind);return;}
  if(wi<0){buyBot(kind);return;}
  var inf=wInfo(wi,kind);
  if(!inf.ok){sfx('deny');shopSay(inf.msg||'ALREADY MAXED');return;}
  if(credits<inf.cost){sfx('deny');shopSay('NOT ENOUGH CREDITS');return;}
  credits-=inf.cost;sfx('buy');
  if(kind==='unlock'){owned[wi]=true;ammo[wi]=WEAP[wi].start;mag[wi]=WEAP[wi].mag;shopSay('UNLOCKED: '+WEAP[wi].name+' (KEY '+(wi+1)+')');}
  else if(kind==='pevo'){
    pistolLv=2;Object.assign(WEAP[0],LASER_PISTOL);mag[0]=magSize(0);if(player.w===0)reloadT=0;sfx('evolve');
    shopSay('PISTOL EVOLVED: LASER PISTOL - PIERCING BOLTS, UPGRADES NOW GO TO 6');
  }
  else if(kind==='dmg'){wd[wi]++;shopSay(WEAP[wi].name+' DAMAGE +20%');}
  else if(kind==='rate'){wr[wi]++;shopSay(WEAP[wi].name+' FIRE RATE +12%');}
  else if(kind==='range'){snR++;WEAP[5].range+=110;shopSay('SNIPER RANGE EXTENDED');}
  else if(kind==='lrange'){rifR++;WEAP[6].range+=110;shopSay('RIFLE LASER SIGHT AND RANGE +110');}
  else{snA++;WEAP[5].mag++;WEAP[5].max+=6;mag[5]=WEAP[5].mag;ammo[5]=Math.min(WEAP[5].max,ammo[5]+6);shopSay('SNIPER MAGAZINE +1, RESERVE +6');}
}
/* ---------- weapon stages (Mk I-III) and attachments, Endless Siege Armory ----------
   Max a weapon's DMG and RATE (sniper: DMG and RANGE), then EVOLVE it. Mk II and Mk III each
   change how it looks, raise its stats and let its upgrades go higher (4, then 6, then 8).
   Every weapon has two attachment slots with two choices each. Slot 1 opens at Mk I, slot 2 at
   Mk II. An attachment is bought once; owned ones swap for free. The pistol's Mk II is the
   Laser Pistol from earlier versions. Story mode keeps its own Armory and doesn't use these. */
var wmk,attOwn,attEq,armTab=0,armSel=0,napN=0;
var MK_COST=[0,220,420],MK_ROMAN=['I','II','III'];
var WSTAGE=[
  ['Laser pistol: piercing bolts','Plasma pistol: every 4th shot bursts'],
  ['Double barrel: +2 pellets, 8 shells','Drum mag: 12 shells, pellets ignite'],
  ['Twin barrels: +150 belt','Incendiary belt: hits can burn'],
  ['Long nozzle: +30% range','Blue flame: double damage'],
  ['6-round drum, bigger blast','Shells split into 3 bomblets'],
  ['Pierces 5 aliens','Kills explode'],
  ['40-round mag, faster','Every 10th round explodes']
];
var ATT=[
  [[{id:'rico',n:'RICOCHET ROUNDS',d:'Bounce to a 2nd alien',c:120},{id:'pmag',n:'EXTENDED MAG',d:'+50% magazine',c:110}],
   [{id:'hair',n:'HAIR TRIGGER',d:'+30% fire rate',c:150},{id:'hollow',n:'HOLLOW POINTS',d:'Crit chance 20% to 35%',c:150}]],
  [[{id:'slug',n:'SLUG BARREL',d:'One heavy piercing shot',c:140},{id:'choke',n:'WIDE CHOKE',d:'12 pellets, wider spread',c:140}],
   [{id:'dragon',n:"DRAGON'S BREATH",d:'Sets aliens on fire',c:170},{id:'flech',n:'FLECHETTES',d:'Pellets pierce one alien',c:170}]],
  [[{id:'stab',n:'STABILIZER',d:'Half the spread',c:130},{id:'drum',n:'DRUM',d:'+50% belt',c:130}],
   [{id:'tesla',n:'TESLA COIL',d:'Every 10th shot chains lightning',c:190},{id:'shred',n:'SHREDDER',d:'Big knockback',c:170}]],
  [[{id:'napalm',n:'NAPALM TANK',d:'Fire stays on the floor',c:180},{id:'wide',n:'WIDE NOZZLE',d:'Wider cone',c:130}],
   [{id:'cryo',n:'CRYO SWAP',d:'Freezes and slows aliens',c:190},{id:'pump',n:'PRESSURE PUMP',d:'+25% damage',c:170}]],
  [[{id:'cluster',n:'CLUSTER SHELLS',d:'4 bomblets on impact',c:190},{id:'sticky',n:'STICKY MINES',d:'Arm on the floor, blow when aliens come',c:180}],
   [{id:'payload',n:'BIG PAYLOAD',d:'+40% blast radius',c:170},{id:'quick',n:'QUICK LOADER',d:'40% faster reload',c:140}]],
  [[{id:'rail',n:'RAIL CORE',d:'Pierces every alien in line',c:220},{id:'mark',n:'MARK SCOPE',d:'Hit aliens take +50% damage',c:200}],
   [{id:'bolt',n:'FAST BOLT',d:'35% faster shots',c:190},{id:'tip',n:'EXPLOSIVE TIP',d:'Small blast where it stops',c:200}]],
  [[{id:'burst',n:'BURST TRIGGER',d:'3-round bursts, tight',c:150},{id:'ap',n:'AP ROUNDS',d:'Pierce one alien',c:170}],
   [{id:'rmag',n:'EXTENDED MAG',d:'+50% magazine',c:130},{id:'tracer',n:'TRACER',d:'+150 sight range, +10% damage',c:140}]]
];
function stageReset(){wmk=WEAP.map(function(){return 1;});attOwn=WEAP.map(function(){return {};});attEq=WEAP.map(function(){return [null,null];});}
stageReset();
function att(wi,id){return !!(attEq&&attEq[wi]&&(attEq[wi][0]===id||attEq[wi][1]===id));}
function evoSecond(wi){return wi===5?snR:wr[wi];}
function evoSecondCap(wi){return wi===5?4:wCap(wi);}
function evoReady(wi){return wd[wi]>=wCap(wi)&&evoSecond(wi)>=evoSecondCap(wi);}
function evoInfo(wi){
  var s=wmk[wi];if(s>=3)return {ok:false,cost:0,label:'FULLY EVOLVED',tag:'MK III'};
  var cost=MK_COST[s],what=wi===5?'DMG AND RANGE':'DMG AND RATE';
  if(!evoReady(wi))return {ok:false,cost:cost,label:'EVOLVE TO MK '+MK_ROMAN[s],tag:'MAX '+what+' FIRST',msg:'MAX '+what+' FIRST'};
  return {ok:true,cost:cost,label:'EVOLVE TO MK '+MK_ROMAN[s]};
}
function applyStage(wi,s){
  var w=WEAP[wi];
  if(wi===0&&s===2){pistolLv=2;Object.assign(w,LASER_PISTOL);}
  else if(wi===1){if(s===2){w.pellets=10;w.mag=8;}else w.mag=12;}
  else if(wi===2&&s===2){w.max+=150;ammo[2]=Math.min(w.max,ammo[2]+150);}
  else if(wi===4&&s===2){w.mag=6;w.radius=143;}
  else if(wi===6&&s===2){w.mag=40;}
  mag[wi]=magSize(wi);if(player&&player.w===wi)reloadT=0;
}
function evolve(wi){
  var inf=evoInfo(wi);
  if(!inf.ok){sfx('deny');shopSay(inf.msg||'ALREADY FULLY EVOLVED');return;}
  if(credits<inf.cost){sfx('deny');shopSay('NOT ENOUGH CREDITS');return;}
  credits-=inf.cost;wmk[wi]++;applyStage(wi,wmk[wi]);sfx('evolve');
  shopSay(WEAP[wi].name+' MK '+MK_ROMAN[wmk[wi]-1]+': '+WSTAGE[wi][wmk[wi]-2].toUpperCase()+'. UPGRADES NOW GO TO '+wCap(wi));
}
function attSlotOpen(wi,slot){return slot===0||wmk[wi]>=2;}
function attBuy(wi,slot,k){
  var a=ATT[wi][slot][k];
  if(!owned[wi]){sfx('deny');shopSay('UNLOCK THE WEAPON FIRST');return;}
  if(!attSlotOpen(wi,slot)){sfx('deny');shopSay('SLOT 2 OPENS AT MK II');return;}
  if(attOwn[wi][a.id]){attEq[wi][slot]=attEq[wi][slot]===a.id?null:a.id;sfx('switch');shopSay((attEq[wi][slot]?'EQUIPPED: ':'REMOVED: ')+a.n);}
  else{
    if(credits<a.c){sfx('deny');shopSay('NOT ENOUGH CREDITS');return;}
    credits-=a.c;attOwn[wi][a.id]=true;attEq[wi][slot]=a.id;sfx('buy');shopSay('EQUIPPED: '+a.n+' - '+a.d.toUpperCase());
  }
  mag[wi]=Math.min(mag[wi],magSize(wi));
}
/* effects the attachments and stages add to bullets */
function miniBlast(x,y,R,dmg,col){
  rings.push({x:x,y:y,r:R,life:0.25,max:0.25,col:col});burst(x,y,12,[col,'#ffffff'],R*3,0.35,4);shake(2);sfx('hit');
  for(var i=0;i<enemies.length;i++){var e=enemies[i];if(e.dead)continue;var dx=e.x-x,dy=e.y-y,d=Math.hypot(dx,dy)||1;
    if(d<R+e.r)hitEnemy(e,dmg*(1-0.5*d/(R+e.r)),dx/d,dy/d,200,true);}
}
function shotFx(b,e){
  if(b.burn&&!e.dead&&!e.shield)e.burn=2;
  if(b.plasma)miniBlast(b.x,b.y,60,b.dmg*0.8,'#c08aff');
  if(b.boomer)miniBlast(b.x,b.y,70,b.dmg*1.5,'#ffb040');
}
function ricochet(b,e){       // send the bullet on to the nearest other alien
  var best=null,bd=280;
  for(var i=0;i<enemies.length;i++){var o=enemies[i];if(o===e||o.dead||o.hidden)continue;var d=Math.hypot(o.x-b.x,o.y-b.y);if(d<bd){bd=d;best=o;}}
  if(!best)return false;
  var sp=Math.hypot(b.vx,b.vy)||600,dx=best.x-b.x,dy=best.y-b.y,dl=Math.hypot(dx,dy)||1;
  b.vx=dx/dl*sp;b.vy=dy/dl*sp;b.life=Math.max(b.life,dl/sp+0.08);b.ricoed=true;b.hits=b.hits||[];b.hits.push(e);if(b.type==='laser')b.pierce=0;
  b.col='#5ac8ff';burst(b.x,b.y,4,['#5ac8ff','#ffffff'],180,0.2,3);
  return true;
}
function chill(e){
  if(e.dead||e.mode==='evolve')return;
  if(!(e.chillT>0)){e.sp0=e.sp;e.sp*=isBoss(e)?0.75:0.5;}
  e.chillT=1.3;e.burn=0;
}
function addPMine(x,y,R,dmg){
  if(pmines.length>=8){var old=pmines.shift();explode(old.x,old.y,old.R,old.dmg,0);}
  pmines.push({x:x,y:y,R:R,dmg:dmg,t:20,arm:0.4});sfx('switch');
}

function inRect(r,x,y){return x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h;}
function shopProceed(){
  if(between&&clearT<=0&&!story)startWave(wave+1);else shopOpen=false;
}

/* ---------- story armory: few expensive, game-changing buys ---------- */
var ocl=0,armor=false,strikes=0,lives=0,airs=[];
function sUnlock(wi,price,label,desc){return {id:'u'+wi,name:label,desc:desc,icon:['pistol','shotgun','minigun','flamer','launcher','sniper','rifle'][wi],cost:function(){return price;},
  can:function(){return !owned[wi];},lvl:function(){return owned[wi]?'OWNED':'';},buy:function(){owned[wi]=true;ammo[wi]=WEAP[wi].start;mag[wi]=WEAP[wi].mag;}};}
var SSHOP=[
  {id:'ammo',name:'AMMO RESUPPLY',desc:'Tops up every weapon you own',icon:'ammo',cost:function(){return 60;},can:function(){return SHOP[0].can();},lvl:function(){return '';},buy:function(){SHOP[0].buy();}},
  {id:'med',name:'MEDKIT',desc:'+50 health',icon:'medkit',cost:function(){return 50;},can:function(){return player.hp<player.maxHp;},lvl:function(){return '';},buy:function(){SHOP[1].buy();}},
  {id:'maxhp',name:'ARMOR PLATING',desc:'+25 max health, heals 25',icon:'maxhp',cost:function(){return 150+up.max*60;},can:function(){return up.max<4;},lvl:function(){return up.max+'/4';},buy:function(){SHOP[2].buy();}},
  {id:'ocl',name:'WEAPON OVERCLOCK',desc:'ALL weapons +25% damage, +15% fire rate',icon:'dmg',cost:function(){return [500,900,1400][ocl]||0;},can:function(){return ocl<3;},lvl:function(){return ocl+'/3';},buy:function(){ocl++;}},
  {id:'armor',name:'NANO ARMOR',desc:'Take 30% less damage from everything',icon:'armor',cost:function(){return 800;},can:function(){return !armor;},lvl:function(){return armor?'OWNED':'';},buy:function(){armor=true;}},
  {id:'air',name:'ORBITAL STRIKE',desc:'Press G: huge blast at your cursor (hold 3)',icon:'strike',cost:function(){return 350;},can:function(){return strikes<3;},lvl:function(){return strikes+'/3';},buy:function(){strikes++;}},
  {id:'tur',name:'AUTO-TURRET',desc:'Press T to drop. Shreds aliens up close (max 3)',icon:'turret',cost:function(){return 250;},can:function(){return turretCount()<3;},lvl:function(){return turretCount()+'/3';},buy:function(){turInv++;}},
  {id:'life',name:'EXTRA LIFE',desc:'Revive once at 50% health',icon:'heart',cost:function(){return 1000;},can:function(){return lives<1;},lvl:function(){return lives?'READY':'';},buy:function(){lives++;}},
  {id:'bot',name:'COMBAT BOT',desc:'Roams, shoots, decoys (Q)',icon:'bot',cost:function(){return bot&&botStage===1?900:300;},
    can:function(){return !bot||botStage===1;},lvl:function(){return bot?(botStage===2?'MK-II':'MK-I'):'';},
    buy:function(){if(!bot){botOwned=true;spawnBot();}else{bl={dmg:4,spd:4,hp:4};botStage=2;var x=bot.x,y=bot.y;bot=null;spawnBot();bot.x=x;bot.y=y;sfx('evolve');}}},
  {id:'lp',name:'LASER PISTOL',desc:'Pistol fires piercing laser bolts',icon:'laserpistol',cost:function(){return 450;},can:function(){return pistolLv<2;},lvl:function(){return pistolLv===2?'OWNED':'';},
    buy:function(){pistolLv=2;Object.assign(WEAP[0],LASER_PISTOL);mag[0]=magSize(0);}},
  sUnlock(3,220,'FLAMETHROWER','Burns crowds, ignores armor'),
  sUnlock(4,300,'GRENADE LAUNCHER','Explosive rounds, hits through armor'),
  sUnlock(6,350,'LASER RIFLE','Auto-aim laser sight'),
  sUnlock(5,700,'HEAVY SNIPER','Piercing rail shot'),
  {id:'dstr',name:'DASH STRIKE',desc:'Dash through aliens to hit them',icon:'dash',cost:function(){return dashInfo('dstr').cost;},can:function(){return up.dash<3;},lvl:function(){return up.dash+'/3';},buy:function(){up.dash++;}},
  {id:'dspd',name:'DASH SPEED',desc:'Faster dash, shorter recharge',icon:'bolt',cost:function(){return dashInfo('dspd').cost;},can:function(){return up.dspd<3;},lvl:function(){return up.dspd+'/3';},buy:function(){up.dspd++;}},
  {id:'drng',name:'DASH RANGE',desc:'Dash travels much further',icon:'range',cost:function(){return dashInfo('drng').cost;},can:function(){return up.drng<3;},lvl:function(){return up.drng+'/3';},buy:function(){up.drng++;}}
];
function sshopLayout(){
  var pw=Math.min(860,LW-40),ph=Math.min(600,LH-30),px=(LW-pw)/2,py=(LH-ph)/2,cw=(pw-50)/2,rh=Math.min(54,(ph-150)/8),r=[];
  for(var i=0;i<SSHOP.length;i++){var col=i<8?0:1,row=i<8?i:i-8;r.push({x:px+20+col*(cw+10),y:py+82+row*rh,w:cw,h:rh-6});}
  return {x:px,y:py,w:pw,h:ph,rows:r,btn:{x:px+20,y:py+ph-56,w:pw-40,h:38}};
}
function sbuy(i){
  var it=SSHOP[i];if(!it)return;
  if(!it.can()){sfx('deny');shopSay(it.lvl()?'ALREADY OWNED OR MAXED':'NOT NEEDED RIGHT NOW');return;}
  var c=it.cost();if(credits<c){sfx('deny');shopSay('NOT ENOUGH CREDITS - NEED '+(c-credits)+' MORE');return;}
  credits-=c;it.buy();sfx(c>=500?'evolve':'buy');shopSay('ACQUIRED: '+it.name);
}
function drawStoryShop(){
  ctx.fillStyle='rgba(2,6,10,0.78)';ctx.fillRect(0,0,LW,LH);
  var L=sshopLayout(),i;
  panel(L.x,L.y,L.w,L.h,0.95);
  txt('ARMORY',L.x+22,L.y+30,26,ACC);txt('STORY MODE  -  BIG-TICKET GEAR',L.x+160,L.y+32,12,'#9fb8c4');
  txt('CREDITS: '+credits,L.x+L.w-22,L.y+30,20,'#5dff8a','right');
  txt(shopMsg.t>0?shopMsg.text:'No small upgrades here: every purchase changes how you fight. Click to buy.',L.x+22,L.y+58,12,shopMsg.t>0?'#ffd76a':'#7f97a3',null,'normal');
  for(i=0;i<SSHOP.length;i++){
    var it=SSHOP[i],r=L.rows[i],c=it.cost(),ok=it.can(),aff=credits>=c,hov=inRect(r,mouse.x,mouse.y),dim=!ok||!aff,big=c>=500&&ok;
    ctx.fillStyle=hov&&!dim?'rgba(47,245,192,0.2)':big?'rgba(255,170,60,0.07)':'rgba(255,255,255,0.045)';ctx.fillRect(r.x,r.y,r.w,r.h);
    ctx.strokeStyle=hov?ACC:big?'rgba(255,170,60,0.45)':'rgba(120,150,165,0.35)';ctx.lineWidth=1;ctx.strokeRect(r.x+0.5,r.y+0.5,r.w-1,r.h-1);
    icon(it.icon,r.x+22,r.y+r.h/2,24,dim);
    txt(it.name+(it.lvl()&&it.lvl()!=='OWNED'&&it.lvl()!=='READY'?'  ['+it.lvl()+']':''),r.x+44,r.y+r.h/2-8,13,dim?'#6f8089':big?'#ffd28a':'#eafff8');
    txt(it.desc,r.x+44,r.y+r.h/2+8,10,'#7f97a3',null,'normal');
    txt(ok?c+' CR':it.lvl()==='OWNED'||it.lvl()==='READY'||it.lvl()==='MK-II'?it.lvl():it.lvl()?'MAXED':'FULL',r.x+r.w-12,r.y+r.h/2,14,!ok?'#55656e':aff?'#5dff8a':'#ff6a5a','right');
  }
  var b=L.btn,bh=inRect(b,mouse.x,mouse.y);
  ctx.fillStyle=bh?'#2ff5c0':'rgba(47,245,192,0.78)';ctx.fillRect(b.x,b.y,b.w,b.h);
  txt('RESUME  (B)',b.x+b.w/2,b.y+b.h/2+1,18,'#03130f','center');
}
function callStrike(){
  if(strikes<=0){floatTxt(player.x,player.y-26,'NO ORBITAL STRIKES - BUY IN ARMORY','#ff6a5a');sfx('deny');return;}
  var x=clamp(mouse.x+cam.x,T,WW-T),y=clamp(mouse.y+cam.y,T,WH-T);
  strikes--;airs.push({x:x,y:y,t:1.0,max:1.0});sfx('charge');floatTxt(x,y-40,'ORBITAL STRIKE INBOUND','#ffd76a');
}
function updateAirs(){
  for(var i=airs.length-1;i>=0;i--){var a=airs[i];a.t-=DT;
    if(a.t<=0){airs.splice(i,1);explode(a.x,a.y,250,650,0);explode(a.x,a.y,120,300,0);flashT=0.3;shake(18);sfx('bossboom');
      rings.push({x:a.x,y:a.y,r:420,life:0.7,max:0.7,col:'#ffd76a'});burst(a.x,a.y,90,['#ffffff','#ffd76a','#ff8a2a','#9af6ff'],800,1,8);scorch(a.x,a.y,120);}}
}
function drawAirs(){
  for(var i=0;i<airs.length;i++){var a=airs[i],k=1-a.t/a.max;
    ctx.strokeStyle='rgba(255,215,106,0.9)';ctx.lineWidth=3;ctx.beginPath();ctx.arc(a.x,a.y,250,0,TAU);ctx.stroke();
    ctx.fillStyle='rgba(255,215,106,'+(0.06+k*0.14)+')';ctx.fill();
    ctx.beginPath();ctx.arc(a.x,a.y,250*k,0,TAU);ctx.stroke();
    ctx.beginPath();ctx.moveTo(a.x-40,a.y);ctx.lineTo(a.x+40,a.y);ctx.moveTo(a.x,a.y-40);ctx.lineTo(a.x,a.y+40);ctx.stroke();
    ctx.save();ctx.globalCompositeOperation='lighter';ctx.globalAlpha=0.3+k*0.6;ctx.fillStyle='#ffffff';ctx.fillRect(a.x-4-k*14,a.y-2000,8+k*28,2000);ctx.restore();}
}

