      if(Math.random()<0.55){var qa=rand(0,TAU),qd=rand(0,e.r);burst(e.x+Math.cos(qa)*qd,e.y+Math.sin(qa)*qd,6,BLOODS.concat(['#ffffff']),300,0.5,5);}
      if(Math.random()<0.12){var qa2=rand(0,TAU);rings.push({x:e.x+Math.cos(qa2)*e.r*0.7,y:e.y+Math.sin(qa2)*e.r*0.7,r:60,life:0.2,max:0.2,col:'#ffffff'});sfx('die_exploder');shake(3);splat(e.x,e.y,1.5,Math.cos(qa2),Math.sin(qa2));}
      if(e.dying<=0){e.final=true;killEnemy(e,0,0);}
