    var dx=player.x-e.x,dy=player.y-e.y,dist=Math.hypot(dx,dy)||1,sp=e.sp,toP=Math.atan2(dy,dx);
    var ang=e.type==='flyer'?toP+Math.sin(stateT*3+e.ph)*0.55:steer(e);
    e.tbT-=DT;if(e.tauntT>0)e.tauntT-=DT;
    if(bot&&e.tauntT>0)e.tb=true;
    else if(e.tbT<=0){
      e.tbT=0.4;e.tb=false;
      if(bot&&!isBoss(e)&&e.type!=='spitter'&&e.type!=='node'){var tbd=Math.hypot(bot.x-e.x,bot.y-e.y);e.tb=bot.decoyT>0?tbd<560:(tbd<320&&tbd<dist);}
    }
    if(e.tb&&bot){
      var bdx=bot.x-e.x,bdy=bot.y-e.y,bdd=Math.hypot(bdx,bdy)||1;
      ang=Math.atan2(bdy,bdx)+(e.type==='flyer'?Math.sin(stateT*3+e.ph)*0.4:0);
      if(e.type==='exploder'&&bdd<e.r+bot.r+16){killEnemy(e,0,0);continue;}
      if(bdd<e.r+bot.r+5){
        e.x-=bdx/bdd*(e.r+bot.r+5-bdd);e.y-=bdy/bdd*(e.r+bot.r+5-bdd);
        if(e.dmg>0&&e.atk<=0){e.atk=0.7;botHurt(e.dmg);}
      }
    }else e.tb=false;
    e.near=dist<210;
    if(e.burn>0&&(e.shield||e.hidden))e.burn=0;
    if(e.markT>0)e.markT-=DT;
    if(e.chillT>0){e.chillT-=DT;if(Math.random()<0.25)part(e.x+rand(-e.r,e.r),e.y+rand(-e.r,e.r),0,rand(-30,-10),0.4,'#bff4ff',4,0.95);if(e.chillT<=0&&e.sp0){e.sp=e.sp0;e.sp0=0;}}
