      var bx=c.x+19,by=c.y+19;
      ctx.fillStyle='rgba(0,0,0,0.35)';ctx.beginPath();ctx.arc(bx+4,by+6,19,0,TAU);ctx.fill();
      ctx.fillStyle=c.hit>0?'#fff':'#8a1f1a';ctx.beginPath();ctx.arc(bx,by,19,0,TAU);ctx.fill();
      ctx.strokeStyle='#3d0c0a';ctx.lineWidth=3;ctx.stroke();
      ctx.fillStyle='#f0c030';ctx.beginPath();ctx.arc(bx,by,12,0,TAU);ctx.fill();
      ctx.fillStyle='#1a1408';ctx.beginPath();ctx.moveTo(bx,by-8);ctx.lineTo(bx+7,by+5);ctx.lineTo(bx-7,by+5);ctx.closePath();ctx.fill();
      ctx.fillStyle='#f0c030';ctx.fillRect(bx-1,by-3,2,5);
