    ctx.fillStyle=c.hit>0?'#ffffff':(c.v===0?'#aab4bc':c.v===1?'#9aa6b0':'#b6c0c7');ctx.fillRect(c.x,c.y,c.w,c.h);
    ctx.strokeStyle='#4e5a66';ctx.lineWidth=3;ctx.strokeRect(c.x+1.5,c.y+1.5,c.w-3,c.h-3);
    ctx.fillStyle='#e8892a';ctx.fillRect(c.x+3,c.y+3,9,9);ctx.fillRect(c.x+c.w-12,c.y+3,9,9);ctx.fillRect(c.x+3,c.y+c.h-12,9,9);ctx.fillRect(c.x+c.w-12,c.y+c.h-12,9,9);
    ctx.fillStyle=c.v===1?'#2a6fd8':'#d83a3a';ctx.fillRect(c.x+c.w/2-3,c.y+c.h/2-9,6,18);ctx.fillRect(c.x+c.w/2-9,c.y+c.h/2-3,18,6);
