// carve shapes: ['c',cx,cy,r] circle, ['l',x1,y1,x2,y2,width] tunnel, ['r',x,y,w,h] rect (tile units)
function carveOpen(def){
  var open=new Uint8Array(def.w*def.h),i,x,y;
  def.carve.forEach(function(s){
    for(y=1;y<def.h-1;y++)for(x=1;x<def.w-1;x++){
      var px=x+0.5,py=y+0.5,ok=false;
      if(s[0]==='c')ok=(px-s[1])*(px-s[1])+(py-s[2])*(py-s[2])<=s[3]*s[3];
      else if(s[0]==='r')ok=px>=s[1]&&px<=s[1]+s[3]&&py>=s[2]&&py<=s[2]+s[4];
      else{var dx=s[3]-s[1],dy=s[4]-s[2],L=dx*dx+dy*dy||1,t=clamp(((px-s[1])*dx+(py-s[2])*dy)/L,0,1),qx=s[1]+dx*t-px,qy=s[2]+dy*t-py;ok=qx*qx+qy*qy<=(s[5]/2)*(s[5]/2);}
      if(ok)open[y*def.w+x]=1;}
  });
  return open;
}
function carveWalls(def){
  var open=carveOpen(def),runs=[],x,y;
  for(y=1;y<def.h-1;y++){var sx=-1;for(x=1;x<=def.w-1;x++){var closed=x<def.w-1&&!open[y*def.w+x];if(closed&&sx<0)sx=x;if(!closed&&sx>=0){runs.push([sx,y,x-sx,1,'rock']);sx=-1;}}}
  def.openMask=open;
  if(!def.vents){
    var cand=[],st=[def.start[0]/T,def.start[1]/T];
    for(y=2;y<def.h-2;y++)for(x=2;x<def.w-2;x++){var all=true;for(var k=-1;k<=1&&all;k++)for(var j=-1;j<=1;j++)if(!open[(y+k)*def.w+x+j]){all=false;break;}
      if(all&&Math.hypot(x-st[0],y-st[1])>9)cand.push([x,y]);}
    var v=[];shuffle(cand);cand.forEach(function(c){if(v.length<9&&v.every(function(o){return Math.hypot(o[0]-c[0],o[1]-c[1])>6;}))v.push(c);});
    def.vents=v;
  }
  return runs;
}
function bakeCave(g){
  var x,y,k,o=MAP.openMask;
  for(k=0;k<90;k++){var bx=rand(T,WW-T),by=rand(T,WH-T);g.fillStyle='rgba('+pick(['60,44,40','40,30,30','70,56,44'])+','+rand(0.15,0.35)+')';g.beginPath();g.ellipse(bx,by,rand(30,110),rand(20,70),rand(0,3),0,TAU);g.fill();}
  for(k=0;k<260;k++){g.fillStyle=pick(['#3a2e2a','#2a2220','#4a3a32']);g.beginPath();g.arc(rand(T,WW-T),rand(T,WH-T),rand(2,6),0,TAU);g.fill();}
  for(k=0;k<40;k++){var fx=rand(T,WW-T),fy=rand(T,WH-T),c=pick(['47,245,192','120,255,90','90,200,255']);for(var q=0;q<4;q++){g.fillStyle='rgba('+c+',0.5)';g.beginPath();g.arc(fx+rand(-10,10),fy+rand(-10,10),rand(2,4),0,TAU);g.fill();}
    var gr=g.createRadialGradient(fx,fy,0,fx,fy,40);gr.addColorStop(0,'rgba('+c+',0.12)');gr.addColorStop(1,'rgba('+c+',0)');g.fillStyle=gr;g.fillRect(fx-40,fy-40,80,80);}
  // organic rock rims where rock meets floor
  for(y=1;y<MH-1;y++)for(x=1;x<MW-1;x++){if(!solid[y*MW+x]||o[y*MW+x])continue;
    var cx=(x+0.5)*T,cy=(y+0.5)*T;
    [[1,0],[-1,0],[0,1],[0,-1]].forEach(function(d){if(o[(y+d[1])*MW+x+d[0]]){for(var r2=0;r2<3;r2++){var ex=cx+d[0]*T*0.45+(d[1]?rand(-24,24):0),ey=cy+d[1]*T*0.45+(d[0]?rand(-24,24):0),rr=rand(12,20);
      g.fillStyle='#3a2c2c';g.beginPath();g.arc(ex+d[0]*3,ey+d[1]*3,rr,0,TAU);g.fill();g.fillStyle='#211819';g.beginPath();g.arc(ex,ey,rr,0,TAU);g.fill();}}});}
  if(MAP.lair)bakeLair(g);
}
function bakeLair(g){
  var cx=25*T,cy=16*T,i;
  for(i=0;i<26;i++){var a=rand(0,TAU),d=rand(120,820),x=cx+Math.cos(a)*d,y=cy+Math.sin(a)*d;g.strokeStyle='rgba(20,10,14,0.7)';g.lineWidth=3;
    for(var c=0;c<3;c++){g.beginPath();g.moveTo(x+c*9,y);g.lineTo(x+c*9+30,y+55);g.stroke();}}
  g.strokeStyle='rgba(56,232,255,0.25)';g.lineWidth=6;
  for(i=0;i<12;i++){var a2=i/12*TAU;g.beginPath();g.moveTo(cx+Math.cos(a2)*120,cy+Math.sin(a2)*120);g.quadraticCurveTo(cx+Math.cos(a2+0.4)*500,cy+Math.sin(a2+0.4)*400,cx+Math.cos(a2+0.2)*880,cy+Math.sin(a2+0.2)*780);g.stroke();}
  g.strokeStyle='rgba(56,232,255,0.4)';g.lineWidth=5;g.beginPath();g.arc(cx,cy,260,0,TAU);g.stroke();g.setLineDash([24,16]);g.beginPath();g.arc(cx,cy,300,0,TAU);g.stroke();g.setLineDash([]);
  for(i=0;i<70;i++){var sx=rand(cx-860,cx+860),sy=rand(cy-760,cy+760);g.fillStyle='rgba(180,240,255,'+rand(0.2,0.5)+')';g.beginPath();g.moveTo(sx,sy);g.lineTo(sx+rand(-10,10),sy+rand(4,14));g.lineTo(sx+rand(4,12),sy+rand(-4,6));g.fill();}
  // the empty Specimen 0 tube it dragged down here
  var tx=25*T,ty=3.6*T;g.fillStyle='#0a1418';g.beginPath();g.arc(tx,ty,70,0,TAU);g.fill();g.strokeStyle='#9fb2bf';g.lineWidth=10;g.beginPath();g.arc(tx,ty,70,0.4,2.3);g.stroke();g.beginPath();g.arc(tx,ty,70,3.3,5.4);g.stroke();
  g.fillStyle='rgba(56,232,255,0.25)';g.beginPath();g.ellipse(tx,ty+40,90,30,0,0,TAU);g.fill();
  g.font='bold 20px "Consolas","Courier New",monospace';g.textAlign='center';g.textBaseline='middle';g.fillStyle='rgba(122,240,255,0.6)';g.fillText('SPECIMEN 0',tx,ty+100);
  g.font='bold 46px "Consolas","Courier New",monospace';g.fillStyle='rgba(122,240,255,0.12)';g.fillText("ZERO'S LAIR",cx,30*T);
}
function drawCaveWall(g,w,X,Y,Wd,Hd){
  if(w.kind==='rock'){g.fillStyle='#120c0e';g.fillRect(X,Y,Wd,Hd);for(var k=0;k<Wd*Hd/900;k++){g.fillStyle=pick(['#1a1214','#0c0809','#21181a']);g.beginPath();g.arc(X+rand(0,Wd),Y+rand(0,Hd),rand(6,16),0,TAU);g.fill();}return true;}
  if(w.kind==='tube'){var cx=X+Wd/2,cy=Y+Hd/2;g.fillStyle='rgba(0,0,0,0.4)';g.beginPath();g.ellipse(cx+6,cy+8,Wd*0.5,Hd*0.5,0,0,TAU);g.fill();
    g.fillStyle='#16202a';g.beginPath();g.arc(cx,cy,Wd*0.46,0,TAU);g.fill();g.fillStyle='rgba(56,232,255,0.3)';g.beginPath();g.arc(cx,cy,Wd*0.38,0,TAU);g.fill();
    g.strokeStyle='#9fb2bf';g.lineWidth=7;g.beginPath();g.arc(cx,cy,Wd*0.46,0.6,2.6);g.stroke();g.beginPath();g.arc(cx,cy,Wd*0.46,3.6,5.2);g.stroke();
    for(k=0;k<8;k++){g.fillStyle='rgba(200,240,255,0.7)';var a=rand(0,TAU),d=rand(Wd*0.5,Wd*0.75);g.beginPath();g.moveTo(cx+Math.cos(a)*d,cy+Math.sin(a)*d);g.lineTo(cx+Math.cos(a)*d+8,cy+Math.sin(a)*d-6);g.lineTo(cx+Math.cos(a)*d+3,cy+Math.sin(a)*d+7);g.fill();}return true;}
  if(w.kind==='crystal'){var cx2=X+Wd/2,cy2=Y+Hd/2,n=Wd>T?7:4;g.fillStyle='rgba(0,0,0,0.35)';g.beginPath();g.ellipse(cx2+5,cy2+7,Wd*0.48,Hd*0.42,0,0,TAU);g.fill();
    for(k=0;k<n;k++){var a2=k/n*TAU+rand(-0.3,0.3),L=Wd*rand(0.32,0.55),bw=Wd*0.11;g.fillStyle=k%2?'#38e8ff':'#9af6ff';g.beginPath();g.moveTo(cx2+Math.cos(a2+1.57)*bw,cy2+Math.sin(a2+1.57)*bw);g.lineTo(cx2+Math.cos(a2)*L,cy2+Math.sin(a2)*L);g.lineTo(cx2+Math.cos(a2-1.57)*bw,cy2+Math.sin(a2-1.57)*bw);g.closePath();g.fill();
      g.strokeStyle='rgba(255,255,255,0.6)';g.lineWidth=1.5;g.beginPath();g.moveTo(cx2,cy2);g.lineTo(cx2+Math.cos(a2)*L*0.9,cy2+Math.sin(a2)*L*0.9);g.stroke();}
    g.fillStyle='#e8fbff';g.beginPath();g.arc(cx2,cy2,Wd*0.12,0,TAU);g.fill();return true;}
  return false;
}
