      var r2x=Math.min(c.r2x,30.5*T),r2a=c.r2x>30*T?Math.PI:0;
      if(t<13.7)cineBug('runner',r2x,c.r2y,r2a,10,t*22);
      var fl=Math.floor(t*7)%2===0?0.05:0,pa2=Math.atan2(7*T-7*T,1);
      cinePlayer(c.px,7*T+8,0,t*16,fl);
      if(fl){var tx=!cine.fired.k1?c.r1x:!cine.fired.k2?c.c1x:r2x;ctx.strokeStyle='rgba(255,240,170,0.9)';ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(c.px+26,7*T+11);ctx.lineTo(tx,7*T+rand(-8,8));ctx.stroke();}
      // door to the control room
      ctx.fillStyle=t<12.6?'#2a4a3a':'#16181a';ctx.fillRect(33*T,5*T,T*0.5,4*T);
